(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("farabi-virtuous-city-b",[{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">كتاب آراء أهل المدينة الفاضلة — تأليف أبي نصر الفارابي (طبعة القاهرة ١٩٠٦)<\/span>"},{"sp":"HDR","t":"القول في الموجود الاول"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">بسم الله الرحمن الرحيم هذا كتاب ألفه أبو نصر الفارابي في مبادئ آراء أهل المدينة الفاضلة<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">الموجود الأول هو السبب الأول لوجود سائر الموجودات كلها وهو بريء من جميع انحاء النقص . وكل ما سواه فليس يخلو من أن يكون فيه شيء من انحاء النقص اما واحد واما أكثر من واحد . وأما الاول فهو خلو من انحائها كلها<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فوجوده أفضل الوجود وأقدم الوجود ولا يمكن أن يكون وجود أفضل ولا أقدم من وجوده وهو من فضيلة الوجود في أعلا انحائه . ومن كمال الوجود في أرفع المراتب . ولذلك لا يمكن أن يشوب وجوده وجوهره عدم أصلا .<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والعدم والضد لا يكونان الا فيما دون فلك القمر والعدم هو لا وجود ما شأنه أن يوجد .<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولا يمكن أن يكون له وجود بالقوة ولا على نحو من الانحاء ولا امكان أن لا يوجد ولا بوجه ما من الوجوه . فلهذا هو أزلى دائم الوجود بجوهره وذاته من غير أن يكون به حاجة فى أن يكون أزليا الى شئ آخر يمد بقاءه بل هو بجوهره كاف في بقائه ودوام وجوده .<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولا يمكن أن يكون وجود أصلا مثل وجوده . ولا أيضاً فى مثل مرتبة وجوده وجود يمكن أن يكون له أو يتوفر عليه .<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهو الموجود الذى لا يمكن أن يكون له سبب به أو عنه أو له كان وجوده فانه ليس بمادة ولا قوامه فى مادة ولا فى موضوع أصلا . بل وجوده خلو من كل مادة ومن كل موضوع<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولا أيضاً له صورة . لأن الصورة لا يمكن أن تكون الا فى مادة . ولو كانت له صورة لكانت ذاته مؤتلفة من مادة وصورة ولو كان كذلك لكان قوامه بجزئيه اللذين منهما ائتلف . ولكان لوجوده سبب . فان كل واحد من أجزائه سبب لوجود جملته . وقد وضعنا انه سبب أول<\/span>","st":"5"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولا أيضاً لوجوده غرض وغاية حتى يكون انما وجوده ليتم تلك الغاية وذلك الغرض . والا لكان يكون ذلك سبباً ما لوجوده فلا يكون سببا أولا . ولا أيضا استفاد وجوده من شيء آخر أقدم منه وهو من أن يكون استفاد ذلك مما هو دونه أبعد<\/span>","st":"6"},{"sp":"HDR","t":"القول في نفي الشريك عنه تعالى"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهو مباين بجوهره لكل ما سواه ولا يمكن أن يكون الوجود الذي له لشيء آخر سواه لان كل ما وجوده هذا الوجود لا يمكن أن يكون بينه وبين شيء آخر له أيضاً هذا الوجود مباينة أصلا . ولا تغاير أصلا . فلا يكون اثنان بل يكون هناك ذات واحدة فقط<\/span>","st":"6"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">لانه ان كانت بينهما مباينة كان الذي تباينا به غير الذي اشتركا فيه . فيكون الشيء الذي باين به كل واحد منهما الآخر جزءاً مما به قوام وجودهما . والذي اشتركا فيه هو الجزء الآخر فيكون كل واحد منهما بالقول ويكون كل واحد من جزئيه سببا لقوام ذاته . فلا يكون أولا بل يكون هناك موجود آخر أقدم منه هو سبب لوجوده وذلك محال<\/span>","st":"6"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان كان ذلك الآخر هو الذي فيه ما باين به هذا ولم يكن في هذا شيء يباين به ذلك الا بعد الشيء الذي به باين ذلك . لزم أن يكون الشيء الذي به باين ذلك الآخر هذا هو الوجود الذى يخص ذاك . ووجود هذا مشترك لهما فاذن ذلك الآخر وجوده مركب من شيئين . من شئ يخصه . ومن شئ يشارك به هذا . فليس اذن وجود ذاك هو وجود هذا بل ذات هذا بسيط غير منقسم . وذات ذلك منقسم فلذلك اذن جزآن بهما قوامه . فلوجوده اذن سبب فوجوده اذن دون وجود هذا وأنقص منه . فليس هو اذن من الوجود فى الرتبة الاولى<\/span>","st":"6"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فانه لو كان مثل وجوده فى النوع خارجاً منه بشئ آخر لم يكن تام الوجود . لان التام هو ما لا يمكن ان يوجد خارجاً منه وجود من نوع وجوده . وذلك فى أى شئ كان . لان التام فى العظم هو ما لا يوجد عظم خارجاً منه . والتام فى الجمال هو الذى لا يوجد جمال من نوع جماله خارجاً منه وكذلك التام فى الجوهر هو ما لا يوجد شئ من نوع جوهره خارجاً منه وكذلك كل ما كان من الاجسام تاماً . لم يمكن أن يكون من نوعه شئ آخر غيره . مثل الشمس والقمر وكل واحد من الكواكب الاخر . واذا كان الاول تام الوجود لم يمكن أن يكون ذلك الوجود لشئ آخر غيره . فاذن هو منفرد بذلك الوجود وحده . فهو واحد من هذه الجهة<\/span>","st":"6"},{"sp":"HDR","t":"القول في نفي الضد عنه"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فانه لا يمكن ان يكون له ضد وذلك يتبين اذا عرف مامعنى الضد . فان الضد مباين للشيء . فلا يمكن ان يكون ضد الشيء هو الشيء أصلاً . ولكن ليس كل مباين هو الضد ولا كل مالم يمكن ان يكون هو الشيء . هو الضد . لكن كل ما كان مع ذلك معانداً . شأنه ان يبطل كل واحد منهما الآخر ويفسده اذا اجتمعا ويكون شأن كل واحد منهما انه ان يوجد حيث الآخر فيه موجود يعدم الآخر . ويعدم من حيث هو موجود فيه لوجود الآخر في الشيء الذي كان فيه الأول . وذلك عام في كل شيء يمكن ان يكون له ضد .<\/span>","st":"7"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فانه ان كان الشيء ضداً للشيء في فعله لا في سائر أحواله فان فعليهما فقط بهذه الصفة . فان كانا متضادين في كيفيتهما . فكيفيتهما بهذه الصفة . وان كانا متضادين في جوهرهما . فجوهرهما في هذه الصفة .<\/span>","st":"7"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان كان الأول له ضد فهو من ضده بهذه الصفة . فيلزم ان يكون شأن كل واحد منهما ان يفسد وان يمكن في الاول ان يبطل عن ضده ويكون ذلك في جوهره . وما يمكن ان يفسد فليس قوامه وبقاؤه في جوهره . بل يكون جوهره غير كاف في ان يبقى موجوداً ولا أيضاً يكون جوهره كافياً في ان يحصل موجوداً بل يكون ذلك بغيره . وأمّا ما أمكن ان لا يوجد فلا يمكن ان يكون أزلياً وما كان جوهره ليس بكاف في بقائه أو وجوده . فلوجوده أو بقائه سبب آخر غيره . فلا يكون أولاً . وأيضاً فان وجوده انما يكون لعدم ضده . فعدم ضده اذن هو سبب وجوده فليس اذن هو السبب الأول على الاطلاق ،<\/span>","st":"7"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فانه يلزم ان يكون لهما أيضاً حيث ما مشترك قابل لهما حتى يمكن بتلاقيهما فيه ان يبطل كل واحد منهما الآخر . إما موضوع أو جنس أو شيء آخر غيرهما . ويكون ذلك ثابتاً ويتعاقب هذان عليه . فذلك اذن هو أقدم وجوداً من كل واحد منهما ،<\/span>","st":"8"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان وضع واضع شيئاً غير ما هو بهذه الصفة ضد الشيء فليس الذي يضعه ضداً . بل مبايناً مباينة أخرى سوى مباينة الضد .<\/span>","st":"8"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ونحن لا ننكر ان يكون للاول مباينات أخر سوى مباينة الضد وسوى ما يوجد وجوده . فاذن لم يمكن ان يكون موجود ما في مرتبة وجوده . لان الضدين هما في رتبة واحدة من الوجود . فاذن الاول منفرد بوجوده لا يشاركه شئ آخر أصلاً موجود في نوع وجوده . فهو اذن واحد وهو مع ذلك منفرد أيضاً برتبته وحده . فهو أيضاً واحد من هذه الجهة<\/span>","st":"8"},{"sp":"HDR","t":"القول في نفي الحد عنه سبحانه"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فانه غير منقسم بالقول الى أشياء بها تجوهره . وذلك لانه لا يمكن ان يكون القول الذى يشرح معناه يدل على جزء من أجزائه أو على جزئيه يتجوهر به . فانه اذا كان كذلك كانت الاجزاء التى بها تجوهره أسباباً لوجوده على جهة ما تكون المعانى التى تدل عليه اجزاء حدّ الشئ أسباباً لوجود المحدود وعلى جهة ما يكون المادة والصورة أسباباً لوجود المتركب منهما . وذلك غير ممكن فيه اذ كان أولاً وكان لا سبب لوجوده أصلاً .<\/span>","st":"8"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذا كان لا ينقسم هذه الاقسام فهو من ان ينقسم أقسام الكمية وسائر انحاء الانقسام أبعدُ . فمن هنا يلزم ضرورة أيضاً ان لا يكون له عظم ولا يكون جسماً أصلاً . فهو أيضاً واحد من هذه الجهة .<\/span>","st":"9"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك ان أحد المعانى التى يقال عليها الواحد هو مالا ينقسم . فان كل شئ كان لا ينقسم من وجه ما . فهو واحد من تلك الجهة التى بها لا ينقسم . فانه ان كان من جهة فعله فهو واحد من تلك الجهة . وان كان من جهة كيفيته فهو واحد من جهة الكيفية . ومالا ينقسم في جوهره فهو واحد في جوهره . فاذن كان الأول غير منقسم في جوهره ،<\/span>","st":"9"},{"sp":"HDR","t":"القول في ان وحدته عين ذاته وانه تعالى عالم وحكيم وانه حق وحي وحيوة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان وجود الذى به ينحاز عما سواه من الموجودات لا يمكن ان يكون غير الذى هو به في ذاته موجود . فلذلك يكون انحيازه عن ماسواه توحده في ذاته .<\/span>","st":"9"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان أحد معانى الوحدة هو الوجود الخاص الذى به ينحاز كل موجود عما سواه وهى التى بها يقال لكل موجود واحد من جهة ماهو موجود الوجود الذى يخصه وهذا المعنى من معانى الواحد يساوق الموجود الأول فالاول أيضا بهذا الوجه واحد وأحق من كل واحد سواه باسم الواحد ومعناه .<\/span>","st":"9"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولانه ليس بمادة ولا مادة له بوجه من الوجوه . فانه بجوهره عقل بالفعل . لان المانع للصورة من ان تكون عقلا وان تعقل بالفعل هو المادة التى فيها يوجد الشئ فمتى كان الشئ في وجوده غير محتاج الى مادة . كان ذلك الشئ بجوهره عقلا بالفعل . وتلك حال الاول . فهو اذن عقل بالفعل . وهو أيضا معقول بجوهره . فان المانع أيضا للشئ من أن يكون بالفعل معقولا هو المادة وهو معقول من جهة ما هو عقل . لأن الذى هويته عقل ليس يحتاج في ان يكون معقولا الى ذات أخرى خارجة عنه تعقله . بل هو بنفسه يعقل ذاته فيصير بما يعقل من ذاته عاقلا وعقلا بالفعل وبأنَّ ذاته تعقله معقولا بالفعل .<\/span>","st":"9"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك لا يحتاج في أن يكون عقلا بالفعل وعاقلا بالفعل الى ذات يعقلها ويستفيدها من خارج بل يكون عقلا وعاقلا بأن يعقل ذاته . فان الذات التى تعقل هى التى تعقل فهو عقل من جهة ما هو معقول فانه عقل وانه معقول وانه عاقل هي كلها ذات واحدة وجوهر واحد غير منقسم ،<\/span>","st":"10"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان الانسان مثلا معقول وليس المعقول منه معقولاً بالفعل . بل كان معقولا بالقوة ثم صار معقولا بالفعل بعد ان عقله العقل فليس اذن المعقول من الانسان هو الذى يعقل . ولا العقل منه أبداً هو المعقول . ولا عقلنا نحن من جهة ما هو عقل هو معقول ونحن عاقلون لا بأنَّ جوهرنا عقل . فان ما نعقل ليس هو الذى به تجوهرنا . فالاول ليس كذلك . بل العقل والعاقل والمعقول فيه معنى واحد . وذات واحدة . وجوهر واحد غير منقسم<\/span>","st":"10"},{"sp":"HDR","t":"Vb. He Is Knowing"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك الحال فى انه عالم فانه ليس يحتاج فى أن يعلم الى ذات أخرى يستفيد بعلمها الفضيلة خارجة عن ذاته . ولا فى ان يكون معلوما الى ذات أخرى تعلمه بل هو مكتف بجوهره فى أن يعلم ويُعلم . وليس علمه بذاته شيئاً سوى جوهره فانه يعلم وانه معلوم وانه علم فهو ذات واحدة وجوهر واحد<\/span>","st":"10"},{"sp":"HDR","t":"Vc. He Is Wise"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك فى انه حكيم . فان الحكمة هى ان العقل فضل الاشياء بأفضل علم وبما يعقل من ذاته ويعلمه يعلم أفضل الاشياء . وأفضل العلم هو العلم الدائم الذى لا يمكن أن يزول وذلك هو علمه بذاته<\/span>","st":"10"},{"sp":"HDR","t":"Vd. He Is True"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك فى انه حق فان الحق يساوق الوجود والحقيقة قد تساوق الوجود فان حقيقة الشئ هو الوجود الذى يخصه وأكمل الوجود الذى هو قسطه من الوجود<\/span>","st":"10"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فان الحق قد يقال على المعقول الذى صادف به العقل الموجود حتى يطابقه . وذلك الموجود من جهة ما هو معقول . يقال له انه حق . ومن جهة ذاته من غير أن يضاف الى ما يعقله يقال انه موجود .<\/span>","st":"11"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالاول يقال انه حق بالوجهين جميعا . بأن وجوده الذى هو له أكمل الوجود . وبانه معقول صادف به الذى عقله الموجود على ما هو موجود .<\/span>","st":"11"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وليس يحتاج فى أن يكون حقا بما هو معقول الى ذات أخرى خارجة عنه تعقله . وأيضاً أولى بما يقال عليه حق بالوجهين جميعاً . وحقيقته ليست هي شيئاً سوى انه حق<\/span>","st":"11"},{"sp":"HDR","t":"Ve. He Is Living and Life"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك فى أنه حىّ وأنه حيوة . فليس يدل بهذين على ذاتين بل على ذات واحدة . فان معنى الحيّ انه يعقل أفضل معقول بأفضل عقل . أو يعلم أفضل معلوم بأفضل علم . كما أن انما يقال لنا احياء أولا . اذا كنا ندرك أحسن المدركات بأحسن ادراك . فانا انما يقال لنا احياء اذا كنا ندرك المحسوسات وهي أحسن المعلومات بالاحساس الذى هو أحسن الادراكات وبأحسن القوى المدركة وهى الحواس .<\/span>","st":"11"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فما هو أفضل عقل اذا عقل وعلم أفضل المعقولات بأفضل علم . فهو أحرى أن يكون حيّاً . لانه يعقل من جهة ما هو عقل وانه عاقل وانه عقل وانه عالم وانه علم هو فيه معنى واحد . وكذلك انه حيّ وأنه حيوة معنى واحد .<\/span>","st":"11"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فان اسم الحي قد يستعار لغير ما هو حيوان . فيقال على كل موجود كان على كماله الاخير وعلى كل ما بلغ من الوجود والكمال الى حيث يصدر عنه ما من شأنه أن يكون منه كما من شأنه أن يكون منه . فعلى هذا الوجه اذا كان الاول وجوده أكمل وجود . كان أيضاً حق باسم الحي من الذي يقال على الشئ باستعارة .<\/span>","st":"11"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكل ما كان وجوده أتم فانه اذا علم وعقل . كان ما يعقل عنه ويعلم منه أتم . اذ كان المعقول منه في نفوسنا مطابقاً لما هو موجود منه . فعلى حسب وجوده الخارج عن نفوسنا يكون معقوله في نفوسنا مطابقاً لوجوده وان كان ناقص الوجود . كان معقوله في نفوسنا معقولاً أنقص<\/span>","st":"11"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان الحركة والزمان والانهاية والعدم وأشباههما من الموجودات . فالمعقول من كل واحد منها في نفوسنا معقول ناقص . اذ كانت هي في أنفسها موجودات ناقصة الوجود والعدد والمثلث والمربع وأشباهها فمعقولاتها في أنفسنا أكمل لانها هي في أنفسها أكمل وجود فلذلك كان يجب في الاول اذ هو فى الغاية من كمال الوجود أن يكون المعقول منه في نفوسنا على نهاية الكمال أيضاً . ونحن نجد الامر على غير ذلك فينبغى أن نعلم أنه من جهته غير معتاص الادراك . اذ كان فى نهاية الكمال . ولكن لضعف قوى عقولنا نحن ولملابستها المادة والعدم يعتاص ادراكه ويعسر علينا تصوره ونضعف من ان نعقله على ماهو عليه وجوده . فان افرط كماله يبهرنا فلانقوى على تصوره على التمام .<\/span>","st":"12"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">كما ان الضوء هو أول المبصرات وأكملها وأظهرها به يصير سائر المبصرات مبصرة . وهو السبب فى ان صارت الالوان مبصرة . ويجب فيها ان يكون كل ما كان أتم وأكبر . كادراك البصر له أتم . ونحن نرى الأمر على خلاف ذلك فانه كلما كان أكبر كان أبصارنا له أضعف . ليس لأجل خفائه ونقصه . بل هو في نفسه على غاية ما يكون من الظهور والاستنارة . ولكن كماله بما هو نور يبهر الابصار فتحار الابصار عنه .<\/span>","st":"12"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">كذلك قياس السبب الاول والعقل الأول والحق الأول . وعقولنا نحن ليس نقص معقوله عندنا لنقصانه في نفسه ولا عسر أدراكنا له لعسره هو في وجوده . لكن لضعف قوي عقولنا نحن . عسر تصوره . فتكون المعقولات التى هى في أنفسنا ناقصة . وتصورنا لها ضعيف .<\/span>","st":"12"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذا على ضربين . ضرب ممتنع من جهة ذاته ان يتصور فيعقل تصوراً تاماً لضعف وجوده ونقصان ذاته وجوهره . وضرب مبذول من جهة فهمه وتصوره على التمام وعلى أكمل ما يكون . ولكن أذهاننا وقوى عقولنا ممتنعة لضعفها وبعدها عن جوهر ذلك الشئ من ان نتصوره على التمام وعلى ما هو عليه من كمال الوجود .<\/span>","st":"13"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذان الضربان كل واحد منهما هو من الآخر في الطرف الاقصى من الوجود . أحدهما في نهاية الكمال . والآخر في نهاية النقص<\/span>","st":"13"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويجب اذ كنا نحن ملتبسين بالمادة . كانت هي السبب في ان صارت جواهرنا جوهراً يبعد عن الجوهر الاول . اذ كلما قربت جواهرنا منه . كان تصورنا له أتم وأيقن وأصدق . وذلك انا كلما كنا أقرب الى مفارقة المادة . كان تصورنا له أتم وانما نصير أقرب اليه بان يصير عقلا بالفعل . واذا فارقنا المادة على التمام يصير المعقول منه في أذهاننا أكمل ما يكون<\/span>","st":"13"},{"sp":"HDR","t":"القول في عظمته وجلاله ومجده تعالى"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك عظمته وجلاله ومجده وان العظمة والجلالة والمجد في الشئ انما يكون بحسب كماله . إما في جوهره . واما في عرض من خواصه . وأكثر ما يقال ذلك فينا . انما هو لكمال مالنا في عرض من أعراضنا . مثل اليسار والعلم وفي شئ من اعراض البدن .<\/span>","st":"13"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاول لما كان كماله بايناً لكل كمال . كانت عظمته وجلاله ومجده بايناً لكل ذي عظمة ومجد<\/span>","st":"13"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكانت عظمته ومجده الغايات فيما له من جوهره لافي شئ آخر خارج عن جوهره وذاته ويكون ذا عظمة في ذاته وذا مجد في ذاته أجله غيره أو لم يجله . عظمه غيره أو لم يعظمه . مجده غيره أم لم يمجده .<\/span>","st":"13"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والجمال والبهاء والزينة في كل موجود . هو أن يوجد وجوده الافضل . ويحصل له كماله الاخير . واذ كان الأول وجوده أفضل الوجود . فجماله فائق لجمال كل ذي الجمال . وكذلك زينته وبهاؤه . ثم هذه كلها له في جوهره وذاته . وذلك في نفسه وبما يعقله من ذاته . وأما نحن فان جمالنا وزينتنا وبهاءنا هي لنا باعراضنا . لا بذاتنا وللاشياء الخارجة عنا . لا في جوهرنا والجمال فيه والكمال ليسا هما فيه سوى ذات واحدة . وكذلك سائرها .<\/span>","st":"13"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واللذة والسرور والغبطة انما ينتج ويحصل أكثر بان يدرك الاجمل والابهى والازين بالادراك الاتقن والاتم . فاذا كان هو الاجمل في النهاية والابهى والازين . فادراكه لذاته الادراك الاتقن في الغاية . وعلمه بجوهره العلم الأفضل على الاطلاق<\/span>","st":"14"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واللذة الذى يلتذ بها الاول لذة لانفهم نحن كنهها ولاندرى مقدار عظمها . إلا بالقياس والاضافة الى مانجده من اللذة عند مانكون قد أدركنا ماهو عندنا أكمل وأبهى ادراكا وأتقن وأتم اما باحساس أو تخيل أو بعلم عقلى . فانا عند هذه الحال يحصل لنا من اللذة مانظن انه فائت لكل لذة في العظم ونكون نحن عند أنفسنا مغبوطين بما نلنا من ذلك غاية الغبطة وان كانت تلك الحال منا يسيرة البقاء سريعة الدثور .<\/span>","st":"14"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فقياس علمه هو وادراكه الافضل من ذاته والاجمل والابهى الى علمنا نحن وادراكنا الاجمل والابهى عندنا . هو قياس سروره ولذته واغتباطه بنفسه الى ماينالنا من اللذة والسرور والاغتباط بانفسنا .<\/span>","st":"14"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واذن كان لانسبة لادراكنا نحن الى ادراكه . ولا لمعلومنا الى معلومه . ولا للاجمل عندنا الى الاجمل من ذاته وان كانت له نسبة فهي نسبة ما يسيرة فاذن لانسبة لالتذاذنا وسرورنا واغتباطنا لانفسنا . الى ما للاول من ذلك . وان كانت له نسبة فهى نسبة يسيرة جداً . فانه كيف يكون نسبة لما هو جزء يسير الى ما مقداره غير متناه في الزمان ولما هو أنقص جداً الى ماهو فى غاية الكمال .<\/span>","st":"14"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان كان ما يلتذ بذاته ويسرّ به أكثر . ويغتبط به اغتباطاً أعظم فهو يحب ذاته ويعشقها ويعجب بها أكثر . فانه بيّنٌ ان الاول يعشق ذاته ويحبها ويعجب بها اعجاباً بنسبته . ونسبته الى عشقنا لما نلتذ به من فضيلة ذاتنا كنسبة فضيلة ذاته هو وكمال ذاته الى فضيلتنا نحن وكمالنا الذى نعجب به من أنفسنا .<\/span>","st":"14"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والحب منه هو المحبوب بعينه . والمعجب منه هو المعجب منه . والعاشق منه هو المعشوق<\/span>","st":"15"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك على خلاف ما يوجد فينا فان المعشوق منا هو الفضيلة والجمال . وليس العاشق منا هو الجمال والفضيلة . لكن للعاشق قوّة أخرى فتلك ليست للمعشوق فليس العاشق منا هو المعشوق بعينه فاما هو فانّ العاشق منه هو بعينه المعشوق والحب هو المحبوب فهو المحبوب الأول والمعشوق الأول أحبّه غيره أو لم يحبه وعشقه غيره أو لم يعشقه<\/span>","st":"15"},{"sp":"HDR","t":"القول فى كيفية صدور جميع الموجودات عنه"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاول هو الذى عنه وُجد ومتى وُجد للاول الوجود الذى هو له لزم ضرورة ان يوجد عنه سائر الموجودات التى وجودُها لا بارادة الانسان واختياره على ماهي عليه من الوجود الذى بعضه مشاهد بالحسّ وبعضه معلوم بالبرهان<\/span>","st":"15"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ووجود ما يوجد عنه انما هو على جهة فيض وجوده لوجود شيء آخر . وعلى ان وجود غيره فائض عن وجوده هو . فعلى هذه الجهة لا يكون وجود ما يوجد عنه سبباً له بوجه من الوجوه ولا على انه غاية لوجود الاول كما يكون وجود الابن من جهة ما هو ابن غايةً لوجود الابوين من جهة ما هما أبوان . يعنى ان الوجود الذى يوجد عنه يفيده كمالاً ما كما يكون لنا ذلك عن جلّ الاشياء التى تكون منا مثل أنا باعطائنا المال لغيرنا نستفيد من غيرنا كرامة أو لذّة أو غير ذلك من الخيرات حتى تكون تلك فاعلة فيه كمالاً ما<\/span>","st":"15"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالاول ليس وجوده لاجل غيره ولا يوجد به غيره حتى يكون الغرض من وجوده ان يوجد سائر الاشياء فيكون لوجوده سبب خارج عنه فلا يكون أولاً ولا أيضاً باعطائه ما سواه الوجود ينال كمالاً لم يكن له قبل ذلك خارجاً عما هو عليه من الكمال كما ينال من يجود بماله أو شيء آخر فيستفيد بما يبذل من ذلك لذة أو كرامة أو رئاسة أو شيئاً غير ذلك من الخيرات .<\/span>","st":"15"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فهذه الاشياء كلها محال ان تكون فى الاول لانه يسقط أوليته وتقدمه ويجعل غيره أقدم منه وسبباً لوجوده<\/span>","st":"16"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">بل وجوده لاجل ذاته يلحق جوهره ووجوده ويتبعه ان يوجد عنه غيره<\/span>","st":"16"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فلذلك وجوده الذى به فاض الوجود الى غيره . هو فى جوهره ووجوده الذى به تجوهره فى ذاته هو بعينه وجوده الذى به يحصل وجود غيره عنه .<\/span>","st":"16"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وليس ينقسم الى شيئين يكون باحدهما تجوهر ذاته وبالآخر حصول شئ آخر عنه . كما ان لنا شيئين تجوهر باحدهما وهو النطق ونكتب بالآخر وهو صناعة الكتابة بل هو ذات واحدة وجوهر واحد به يكون تجوهره وبه بعينه يحصل عنه شئ آخر<\/span>","st":"16"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولا أيضا يحتاج فى ان يفيض عن وجوده وجود شئ آخر الى شئ غير ذاته يكون فيه . ولا عرض يكون فيه ولا حركة يستفيد بها حالا لم يكن له ولا آلة خارجة عن ذاته مثل ما تحتاج النار فى ان يكون عنها وعن الماء بخار الى حرارة يتبخر بها الماء وكما تحتاج الشمس فى أن تسخن مالدينا الى ان تتحرك هى ليحصل لها بالحركة مالم يكن لها من الحال فيحصل عنها وبالحال التى استفادها بالحركة حرارة فيما لدينا .<\/span>","st":"16"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">أو كما يحتاج النجار الى الفاس والى المنشار حتى يحصل عنه فى الخشب انفصال وانقطاع وانشقاق<\/span>","st":"16"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وليس وجوده بما يفيض عنه وجود غيره أكمل من وجوده الذى هو بجوهره ولا وجوده الذى بجوهره أكمل من الذى يفيض عنه وجود غيره . بل هما جميعاً ذات واحدة ولا يمكن أيضاً ان يكون له عائق من أن يفيض عنه وجود غيره لا من نفسه ولا من خارج أصلاً<\/span>","st":"16"},{"sp":"HDR","t":"القول في مراتب الموجودات"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">الموجودات كثيرة وهي مع كثرتها متفاضلة وجوهره جوهر يفيض منه كل وجود (كيف كان ذلك الوجود) كان كاملاً أو ناقصاً وجوهره أيضاً جوهر اذا فاضت منه الموجودات كلها بترتيب مراتبها حصل عنه لكل موجود قسطه الذى له من الوجود ومرتبته منه<\/span>","st":"17"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيبتدئ من أكملها وجوداً ثم يتلوه ما هو أنقص منه قليلاً ثم لا يزال بعد ذلك يتلو الانقص فالانقص الى ان ينتهي الى الموجود الذى ان تخطى عنه الى ما دونه تخطى الى ما لم يمكن ان يوجد أصلاً فتنقطع الموجودات من الوجود وبان جوهره جوهراً تفيض منه الموجودات كلها من غير ان يخص بوجود دون وجوده فهو جواد بوجوده هو في جوهره ويترتب عنه الموجودات ويتحصل لكل موجود قسطه من الوجود بحسب رتبته عنه فهو عدل وعدالته في جوهره وليس ذلك لشئ خارج من جوهره<\/span>","st":"17"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وجوهره أيضاً جوهر اذا حصلت الموجودات مرتبة في مراتبها ان يأتلف ويرتبط وينتظم بعضها مع بعض ائتلافا وارتباطا وانتظاما تصير بها الاشياء الكثيرة جملة واحدة وتحصل كشئ واحد. والتي بها ترتبط هذه وتأتلف هي لبعض الاشياء في جواهرها حتى ان جواهرها التي بها وجودها هي التي بها تأتلف وترتبط ولبعض الاشياء تكون أحوال فيها تابعة لجواهرها مثل المحبة التي بها يرتبط الناس فانها حال فيهم وليست هي جواهرهم التي بها وجودهم وهذه أيضا فيها مستفادة عن الاول لان في جوهر الاول ان يحصل عنه بكثير من الموجودات مع جواهرها الاحوال التي بها يرتبط بعضها مع بعض ويأتلف وينتظم<\/span>","st":"17"},{"sp":"HDR","t":"القول في الاسماء التي ينبغي ان يسمى بها الاول تعالى مجده"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">الاسماء التي ينبغي ان يسمى بها الاول هي الاسماء التي تدل في الموجودات التي لدينا ثم في أفضلها عندنا على الكمال وعلى فضيلة الوجود من غير ان يدل شئ من تلك الاسماء فيه هو على الكمال والفضيلة التي جرت العاده ان تدل عليها تلك الاسماء في الموجودات التي لدينا وفي أفضلها بل على الكمال الذي يخصه هو في جوهره<\/span>","st":"17"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضا فان أنواع الكمالات التي جرت العادة ان يدل عليها بتلك الاسماء الكثيرة كثيرة وليس ينبغي ان تظن بان أنواع كمالاته التي يدل عليها باسمائه الكثيرة أنواع كثيرة ينقسم الاول اليها ويجوهر بجميعها بل ينبغي ان يدل بتلك الاسماء الكثيرة على جوهر واحد ووجود واحد غير منقسم أصلاً<\/span>","st":"18"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاسماء التي تدل على الكمال والفضيلة في الاشياء التي لدينا، منها ما يدل على ما هو للشيء في ذاته لا من حيث هو مضاف الى شيء آخر خارج عنه مثل الموجود والواحد والحيّ ومنها ما يدل على ما هو للشيء بالاضافة الى شيء آخر خارج عنه مثل العدل والجواد. وهذه الاسماء اما فيما لدينا فانها تدل على فضيلة وكمال تكون اضافته الى شيء آخر خارج عنه جزءاً من ذلك الكمال حتى تكون تلك الاضافة جزءاً من جملة ما يدل عليه بتلك الاسماء بان يكون ذلك الاسم، أو بان تكون تلك الفضيلة وذلك الكمال قوامه بالاضافة الى شيء آخر.<\/span>","st":"18"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأمثال هذه الاسماء متى ثقّات وسمّي بها الاول قصدنا ان يدل بها على الاضافة التي له الى غيره بما فاض منه من الوجود فينبغي ان لا نجعل الاضافة جزءاً من كماله ولا أيضاً نجعل ذلك الكمال المدلول عليه بذلك الاسم قوامه بتلك الاضافة بل ينبغي ان ندل به على جوهر وكمال تتبعه ضرورة تلك الاضافة. وعلى ان قوام تلك الاضافة بذلك الجوهر. وعلى ان تلك الاضافة تابعة لما جوهر ذلك الجوهر الذى دل عليه بذلك الاسم<\/span>","st":"18"},{"sp":"HDR","t":"القول فى الموجودات الثوانى وكيفية صدور الكثير"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويفيض من الأول وجود الثانى فهذا الثانى هو أيضاً جوهر غير متجسم أصلاً ولا هو فى مادة . فهو يعقل ذاته ويعقل الأول وليس ما يعقل من ذاته هو شىء غير ذاته فبما يعقل من الاول يلزم عنه وجود ثالث . وبما هو متجوهر بذاته التى تخصه يلزم عنه وجود السماء الاولى .<\/span>","st":"19"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والثالث أيضاً وجوده لا فى مادة وهو بجوهره عقل وهو يعقل ذاته ويعقل الاول فبما يتجوهر به من ذاته التى تخصه يلزم عنه وجود كرة الكواكب الثابتة .<\/span>","st":"19"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وبما يعقله من الاول يلزم عنه وجود رابع وهذا أيضاً لا فى مادة فهو يعقل ذاته ويعقل الاول فبما يتجوهر به من ذاته التى تخصه يلزم عنه وجود كرة زحل . وبما يعقله من الاول يلزم عنه وجود خامس وهذا الخامس أيضاً وجوده لا فى مادة فهو يعقل ذاته ويعقل الاول فبما يتجوهر به من ذاته يلزم عنه وجود كرة المشترى . وبما يعقله من الاول يلزم عنه وجود سادس وهذا أيضاً وجوده لا فى مادة وهو يعقل ذاته ويعقل الاول فبما يتجوهر به من ذاته يلزم عنه وجود كرة المريخ . وبما يعقله من الاول يلزم عنه وجود سابع<\/span>","st":"19"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذا أيضاً وجوده لافي مادة وهو يعقل ذاته ويعقل الاول فيما يتجوهر به من ذاته يلزم عنه وجود كرة الشمس وبما يعقل من الاول يلزم عنه وجود ثامن وهو أيضاً وجوده لافي مادة ويعقل ذاته ويعقل الاول فيما يتجوهر به من ذاته التي تخصه يلزم عنه وجود كرة الزهرة . وبما يعقل من الاول يلزم عنه وجود تاسع وهذا أيضاً وجوده لافي مادة فهو يعقل ذاته ويعقل الاول . فيما يتجوهر به من ذاته يلزم عنه وجود كرة عطارد . وبما يعقل من الاول يلزم عنه وجود عاشر<\/span>","st":"19"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذا أيضاً وجوده لافي مادة وهو يعقل ذاته ويعقل الاول فيما يتجوهر به من ذاته يلزم عنه وجود كرة القمر وبما يعقل من الاول يلزم عنه وجود حادى عشر وهذا الحادى عشر هو أيضاً وجوده لافي مادة وهو يعقل ذاته ويعقل الاول ولكن عنده ينتهى الوجود الذي لا يحتاج ما يوجد ذلك الوجود الى مادة وموضوع أصلاً<\/span>","st":"19"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهى الاشياء المفارقة التى هي فى جواهرها عقول ومعقولات وعند كرة القمر ينتهى وجود الاجسام السماوية وهى التى بطبيعتها تتحرك دوراً<\/span>","st":"20"},{"sp":"HDR","t":"القول فى الموجودات والاجسام التى لدينا"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه الموجودات التى أحصيناها هى التى حصلت لها فى كمالاتها الافضل فى جواهرها منذ أول الامر وعند هذين ينقطع وجود هذه . والتى بعدهما هى التى ليس فى طبيعتها ان توجد فى الكمالات الافضل فى جواهرها منذ أول الامر بل انما شأنها ان يكون لها أولا أنقص وجوداتها فيبتديء منه فيترقي شيئاً فشيئاً الى ان يبلغ كل نوع منها أقصى كماله فى جوهره . ثم هى فى سائر أعراضه . وهذه الحال هى فى طباع هذا الجنس من غير ان يكون ذلك دخيلا عليه من شيء آخر غريب عنه . وهذه منها طبيعية . ومنها إرادية . ومنها مركبة من الطبيعية والارادية . والطبيعية من هذه توطئة للارادية ويتقدم بالزمان وجودها قبل الارادية ولا يمكن وجود الارادية منها دون ان توجد الطبيعية منها قبل ذلك .<\/span>","st":"20"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاجسام الطبيعية من هذه هى الاسطقسات مثل النار والهواء والماء والارض وما جانسها من البخار واللهيب وغير ذلك . والمعدنية مثل الحجارة وأجناسها والنبات والحيوان غير الناطق والحيوان الناطق<\/span>","st":"20"},{"sp":"HDR","t":"القول في المادة والصورة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكل واحد من هذه قوامه من شيئين . أحدهما منزلته منزلة خشب السرير والآخر منزلته منزلة خلقة السرير . فما منزلته الخشب هو المادة والهيولى . وما منزلته خلقته فهو الصورة والهيئة . وما جانس هذين من الاشياء فالمادة موضوعة ليكون بها قوام الصورة . والصورة لا يمكن ان يكون لها قوام ووجود بغير المادة . فالمادة وجودها لاجل الصورة ولو لم تكن صورة ما موجودة لما كانت المادة .<\/span>","st":"20"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والصورة وجودها لا لتوجد بها المادة بل ليحصل الجوهر المتجسم جوهراً بالفعل . فان كل نوع انما يحصل موجوداً بالفعل وبأكمل وجودية اذا حصلت صورته . ومادامت مادته موجودة دون صورته فانه انما هو ذلك النوع بالقوة فان خشب السرير مادام بلا صورة السرير فهو سرير بالقوة وانما يصير سريراً بالفعل اذا حصلت صورته فى مادته وأنقص وجودى الشئ هو بمادته وأكمل وجوديه هو بالصورة<\/span>","st":"21"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وصور هذه الاجسام متضادة وكل واحد منها يمكن ان يوجد وان لا يوجد .<\/span>","st":"21"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومادة كل واحد منها قابلة لصورته ولضدها وممكنة أن توجد فيها صورة الشئ وأن لا توجد بل يمكن أن تكون موجودة فى غير تلك الصورة .<\/span>","st":"21"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاسطقسات أربعٌ وصورها متضادة . ومادة كل واحدة منها قابلة لصورة ذلك الاسطقس ولضدها . ومادة كل واحدة منها مشتركة للجميع وهي مادة لها ولسائر الاجسام الأُخر التي تحت الأجسام السماوية لأن سائر ما تحت السماوية كائنة عن الاسطقسات . وموادُّ الاسطقسات ليست لها مواد فهي المواد الاولى المشتركة لكل ما تحت السماوية وليس شئٌ من هذه يعطى صورته من أول الامر بل كل واحد من الاجسام فانما يُعطى أولاً مادته التى بها وجوده بالقوة البعيدة فقط لا بالفعل إذ كانت انما أعطيت مادته الاولى فقط . ولذلك هي أبداً ساعية الى ما يتجوهر به من الصورة ثم لا يزال يترقى شيئاً بعد شئ الى أن تحصل له صورته التى بها وجوده بالفعل<\/span>","st":"21"},{"sp":"HDR","t":"القول فى المقاسمة بين المراتب والاجسام الهيولانية والموجودات الالهية"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وترتيب هذه الموجودات هو أن تقدّم أولاً أخسها ثم الافضل فالافضل الى أن تنتهي الى أفضلها الذى لا أفضل منه<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فأخسُّها المادة الاولى المشتركة والافضل منها الاسطقسات ثم المعدنية ثم النبات ثم الحيوان غير الناطق ثم الحيوان الناطق وليس بعد الحيوان الناطق أفضل منه<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأما الموجودات التى سلف ذكرها فإنها تترتب أولاً أفضلها ثم الأنقص فالأنقص الى أن ينتهى الى أنقصها. وأفضلها وأكملها الاول.<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فأما الاشياء الكائنة عن الاول فأفضلها بالجملة هي التى ليست بأجسام ولا هي من أجسام. ومن بعدها السماوية. وأفضل المفارقة من هذه هى الثانية ثم سائرها على الترتيب الى أن ينتهي الى الحادى عشر.<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأفضل السماوية هى السماء الاولى ثم الثانية ثم سائرها على الترتيب الى أن ينتهى الى الحادى عشر وهو كرة القمر.<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاشياء المفارقة التى بعد الاولى هى عشرة. والاجسام السماوية في الجملة تسعة فجميعها تسعة عشر.<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكل واحد من العشرة متفرد بوجوده ومرتبته ولا يمكن أن يكون وجوده لشيء آخر غيره لان وجوده إن شاركه فيه آخر فذلك الآخر ان كان غير هذا فباضطرار أن يكون له شيء ما باين به هذا فيكون ذلك الشيء الذى به باين هذا هو وجوده الذى يخصه فيكون الوجود الذى يخص ذلك الشيء ليس هو الذى هو به هذا موجود. فإذن ليس وجودهما وجوداً واحداً بل لكل واحد منهما شيء يخصه.<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولا أيضاً يمكن ان يكون له ضد لان ما كان له ضد فله مادة مشتركة بينه وبين ضده وليس يمكن ان يكون لواحد من هذه مادة .<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً الذي تحت نوع ما انما تكثر أشخاصه لكثرة موضوعات صورة ذلك النوع . فما ليست له مادة فليس يمكن ان يكون في نوعه شئ آخر غيره<\/span>","st":"22"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فان الاضد انما تحدث إما من أشياء جواهرها متضادة . أو من شئ واحد تكون أحواله ونسبه في موضعه متضادة مثل البرد والحر فانهما يكونان عن الشمس ولكن الشمس تكون على حالين مختلفين من القرب والبعد فتحدث بحاليها أحوالا ونسبا متضادة .<\/span>","st":"23"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالاول لا يمكن ان يكون له ضد ولا أحواله متضادة من الثانى ولا نسبته من الثانى نسبة متضادة . والثانى لا يمكن فيه تضاد وكذلك لافي الثالث الى ان ينتهى الى العاشر<\/span>","st":"23"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكل واحد من العشرة يعقل ذاته ويعقل الاول وليس في واحد منها كفاية في ان يكون فاضل الوجود بان يعقل ذاته فقط بل انما يقتبس الفضيلة الكاملة بان يعقل مع ذاته ذات السبب الاول وبحسب زيادة فضيلة الاول على فضيلة ذاته يكون بما عقل الاول فضل اغتباطه بنفسه أكثر من اغتباطه بها عند عقل ذاته . وكذلك زيادة التذاذه بذاته بما عقل الاول على التذاذه بما عقل من ذاته بحسب زيادة كمال الاول على كمال ذاته واعجابه بذاته وعشقه لها بما عقل من الاول على اعجابه بذاته وعشقه لها بما عقل من ذاته بحسب زيادة بهاء الاول وجماله على بهاء ذاته وجمالها فيكون المحبوب أولا والمعجب أولا عند نفسه بما هو يعقله من الاول وثانياً بما هو يعقله من ذاته . فالاول أيضاً بحسب الاضافة الى هذه العشرة هو المحبوب الاول والمعشوق الاول<\/span>","st":"23"},{"sp":"HDR","t":"القول فيما تشترك الاجسام السماوية فيه"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاجسام السماوية تسع جمل في تسع مراتب كل جملة يشتمل عليها جسم واحد كرىّ . فالاول منها يحتوى على جسم واحد فقط فيتحرك حركة واحدة دورية سريعة جداً . والثانى جسم واحد يحتوى على أجسام حركتها مشتركة ولها من الحركة اثنتان فقط يشترك جميعها فى الحركتين جميعاً . والثالث وما بعده الى تمام السبعة يشتمل كل واحد منها على أجسام كثيرة مختلفة فى حركات ما يخص كل واحد منها ويشترك في حركات أخر . وجنس هذه الاجسام كلها واحد ويختلف في الأنواع ولا يمكن أن يوجد في كل نوع منها الا واحد بالعدد لا يشاركه شيء آخر في ذلك النوع فان الشمس لا يشاركها في وجودها شيء آخر من نوعها وهي متفردة بوجودها وكذلك القمر وسائر الكواكب<\/span>","st":"23"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه تجانس الموجودات الهيولانية وذلك ان لها موضوعات تشبه المواد الموضوعة لجمل الصور وأشباههما كالصور والجوهر . وقوام تلك الاشياء في تلك الموضوعات . الا ان صورها لا يمكن ان يكون لها اضداد وموضوع كل واحد منها لا يمكن ان يكون قابلا لغير تلك الصورة ولا يمكن ان يكون خلواً منها ولان موضوعات صورها لا عدم فيها بوجه من الوجوه ولا لصورها اعدام تقابلها فصارت موضوعاتها لا تعوق صورها ان تعقل وان تكون عقولا بذاتها .<\/span>","st":"24"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذن كل واحد من هذه بصورته عقل بالفعل وهو يعقل بها ذات المفارق الذي عنه وجود ذلك الجسم ويعقل الاول .<\/span>","st":"24"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وليس جميع ما يعقل من ذاته عقلا لانه يعقل موضوعه وموضوعه ليس يعقل واذا كان ليس يعقل بموضوعه وانما يعقل بصورته ففيه معقول ليس يعقل فهو يعقل كل ما به تجوهره وتصويره . يعني ان تجوهره بصورة وموضوع وبهذا يفارق الاول والعشرة المتخلصة من الهيولى ومن كل موضوع .<\/span>","st":"24"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويشاركه الانسان فى المادة فهو أيضاً مغتبط بذاته ليس بما يعقل من ذاته فقط ولكن بما يعقل من الاول ثم بما يعقل من ذات المفارق الذى عنه وجوده . ويشارك المفارق فى عشقه للاول وباعجابه بنفسه بما استفاد من بهاء الاول وجماله الا انه فى كل ذلك دون العشرة بكثير .<\/span>","st":"24"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وله من كل ما تشاركه فيه الهيولانية أشرفها وأفضلها وذلك ان له من الاشكال أفضلها وهى الكرية . ومن الكيفيات المرتبات أفضلها وهو الضياء فان بعض أجزائها فاعلة للضياء وهى الكواكب وبعض أجزائها مشفة بالفعل لانها مملوءة نوراً من أنفسها ومما تستفيده من الكواكب . ولها من الحركات أفضلها وهى الحركة الدورية . وتشارك العشرة فى انها أعطيت أفضل ما تجوهر بها من أول أمرها وكذلك أعظامها واشكالها والكيفية المرتبة التى تخصها<\/span>","st":"24"},{"sp":"HDR","t":"القول فيما فيه واليه تتحرك الاجسام السماوية ولاى شئ تتحرك"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويفارقها فى أنها لم يمكن فيها ان تعطى من أول أمرها الشيئ الذى اليه تتحرك وما اليه تتحرك هو من أيسر عرض يكون فى الجسم وأخسه.<\/span>","st":"25"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك ان كل جسم فهو فى أين ما ونوع الأين الذى هو لهذا الجسم هو ان يكون حول جسم ما ونوع أينه هذا النوع. فليس يمكن ان تنتقل جملته عن جملة هذا النوع<\/span>","st":"25"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولكن لهذا النوع أجزاء وللجسم الذى فيه أجزاء وليس جزء من أجزاء هذا الجسم أولى بجزء من أجزاء الحول بل كل جزء من الجسم يلزم ان يكون له كل جزء من أجزاء الحول ولا أيضاً ان يكون أولى به فى وقت دون وقت بل فى كل وقت دائماً وكلما حصل جزء من هذا الجسم فى جزء ما من الحول احتاج الى ان يكون له الجزء الذى قدامه قدامه. ولا يمكن ان يجتمع له الجزآن معا فى وقت واحد<\/span>","st":"25"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيحتاج الى ان يتخلى من الذى هو فيه ويصير الى ماهو قدامه الى ان يستوفى كل جزء من أجزاء الحول. ولان الجزء الذى كان فيه ليس هو فى وقت أولى به من وقت. فيجب ان يكون له ذلك دائما واذا لم يمكن ان يكون ذلك الجزء له دائما على ان يكون واحداً بالعدد وصار واحداً بالنوع بان يوجد له حيناً ولا يوجد له حيناً.<\/span>","st":"25"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم يعود الى شبيهه فى النوع ثم يتخلى عنه أيضاً مدة ثم يعود الى شبيه له ثالث ويتخلى عنه أيضاً مدة ثم يعود الى شبيه له رابع وهذا له أبداً.<\/span>","st":"25"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فظاهر أن التي عنها يتحرك ويتبدل عليها ويعود اليها هي في نسبتها الى الجسم الذي يوجد السماء حوله. ومعنى النسبة أنه يقال هذا لهذا وهذا من هذا وما شاكل ذلك من قبل ان معنى الاين هو نسبة الجسم الى سطح الجسم الذي ينطبق عليه<\/span>","st":"25"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكل جسم سمائي في كرة أي دائرة مجسمة فان نسب أجزائه الى أجزاء سطح ما تحتها من الاجسام تتبدل دائماً ويعود كل واحد منها في المستقبل من الزمان الى أشباه النسب التي سلفت.<\/span>","st":"26"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ونسبة الشئ الى الشئ هي أخسُّ ما يوجد له وأبعد الاعراض عن جوهر الشئ<\/span>","st":"26"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولكل واحد من الاكر والدوائر المجسمة التي فيها حركةٌ على حيالها فاما أسرع أو أبطأ من حركة الاخرى مثل كرة زحل وكرة القمر فان كرة القمر أسرع حركة من كرة زحل<\/span>","st":"26"},{"sp":"HDR","t":"القول في الأحوال التي توجد بها الحركات الدورية وفي الطبيعة المشتركة لها"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وليس هذا التفاضل الذي في حركاتها بحسب اضافتها الى غيرها بل لها في أنفسها وبالذات. والبطيء من هذه بطيء دائماً والسريع سريع دائماً<\/span>","st":"26"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فان كثيراً من السماوية أوضاعها من الوسط ومما تحتها مختلفة ولأجل اختلاف أوضاعها هذه منها تلحق كل واحد من هذه خاصة بالعرض أن يسرع حول الارض أحياناً ويبطئ أحياناً<\/span>","st":"26"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذا سوى سرعة بعضها دائماً وابطاء الآخر دائماً على قياس حركة زحل الى حركة القمر وأنها تلحقها باضافة بعضها الى بعض بأن تجتمع أحياناً وتفترق أحياناً ويكون بعضها من بعض على نسب متضادة . وأيضاً فانها تقرب أحياناً من بعض ماتحتها وتبعد أحياناً عنه وتظهر أحياناً وتستر أحياناً فتلحقها هذه المتضادات لافي جواهرها ولا في الاعراض التي تقرب من جواهرها بل في نسبها<\/span>","st":"26"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك مثل الطلوع والغروب فانها نسبتان لها الى ماتحتها متضادتان .<\/span>","st":"26"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والجسم السماوي أول الموجودات التي تلحقها أشياء متضادة . وأول الاشياء يكون فيها تضاد هي نسب هذا الجسم الى ما تحته ونسب بعضها الى بعض . وهذه المتضادات هي أخس المتضادات . والتضاد نقص في الوجود . فالجسم السمائي يلحقه النقص في أخس الاشياء التي شأنها أن توجد<\/span>","st":"27"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وللاجسام السماوية كلها أيضاً طبيعة مشتركة وهي التي بها صارت تتحرك كلها بحركة الجسم الاول منها حركة دورية في اليوم والليلة وذلك ان هذه الحركة ليست لما تحت السماء الاولى قسراً إذ كان لا يمكن أن يكون في السماء شئ يجرى قسراً ، وبينها أيضاً تباين في جواهرها من غير تضادّ مثل مباينة زحل للمشترى وكل كوكب لكل كوكب وكل كرة لكل كرة ثم يلحقها كما قلنا تضاد في نسبها وان تتبدل تلك النسب ومتضادتها وتتعاقب عليها<\/span>","st":"27"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فتتخلى من نسبة ما وتصير الى ضدها ثم تعود الى ما كانت تخلت منه بالنوع لا بالعدد فيكون لها نسب تتكرر ويعود بعضها في مدة أطول وبعضها في مدة أقصر وأحوال ونسب لا تتكرر أصلاً ويلحقها ان يكون لجماعة منها نسب الى شئ واحد متضادة مثل أن يكون بعضها قريباً من شئ وبعضها بعيداً من ذلك الشئ بعينه<\/span>","st":"27"},{"sp":"HDR","t":"القول في الاسباب التي عنها تحدث الصورة الاولى والمادة الاولى"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيلزم عن الطبيعة المشتركة التى لها وجود المادة الاولى المشتركة لكل ما تحتها وعن اختلاف جواهرها وجود أجسام كثيرة مختلفة الجواهر وعن تضاد نسبها واضافاتها وجود الصور المتضادة وعن تبدل متضادات النسب عليها وتعاقبها تبدل الصور المتضادة على المادة الاولى وتعاقبها<\/span>","st":"27"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وعن حصول نسب متضادة واضافات متعاندة الى ذات واحدة في وقت واحد من جماعة أجسام فيها اختلاط في الاشياء ذات الصور المتضادة وامتزاجاتها وأن يحدث عن أصناف تلك الامتزاجات المختلفة أنواع كثيرة من الاجسام ويحدث عن اضافاتها التي تتكرر وتعود الاشياء التي يتكرر وجودها ويعود بعضها في مدة أقصر وبعضها في مدة أطول وعن ما لا يتكرر من اضافاتها وأحوالها بل انما تحدث في وقت ما من غير أن تكون قد كانت فيما سلف ومن غير أن تحدث فيما بعد الاشياء التي تحدث ولا تتكرر أصلا<\/span>","st":"27"},{"sp":"HDR","t":"القول في مراتب الاجسام الهيولانية في الحدوث"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيحدث أولا الاسطقسات ثم ما جانسها وقارنها من الاجسام مثل البخارات وأصنافها مثل الغيوم والرياح وسائر ما يحدث في الجو وأيضاً مجانساتها حول الارض وتحتها وفي الماء والنار<\/span>","st":"28"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويحدث في الاسطقسات وفي كل واحد من سائر تلك قوى تحرك بها من تلقاء أنفسها الى أشياء شأنها أن توجد لها أو بها بغير محرك من خارج وقوى يفعل بعضها في بعض وقوى يقبل بها بعضها فعل بعض ثم تفعل فيها الاجسام السماوية ويفعل بعضها في بعض فيحدث من اجتماع الافعال من هذه الجهات أصناف من الاختلاطات والامتزاجات كثيرة والمقادير كثيرة مختلفة بغير تضاد ومختلفة بالتضاد .<\/span>","st":"28"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيلزم عنها وجود سائر الاجسام فتختلط أولا الاسطقسات بعضها مع بعض فيحدث من ذلك أجسام كثيرة متضادة ثم تختلط هذه المتضادة بعضها مع بعض فقط وبعضها مع بعض ومع الاسطقسات فيكون ذلك اختلاطا ثانيا بعد الاول فيحدث من ذلك أيضاً أجسام كثيرة متضادة الصور<\/span>","st":"28"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويحدث في كل واحد من هذه أيضاً قوى يفعل بها بعضها في بعض وقوى تقبل بها فعل غيره فيه وقوى تتحرك بها من تلقاء نفسه بغير محرك من خارج ثم تفعل فيها أيضاً الاجسام السماوية ويفعل بعضها في بعض وتفعل فيها الاسطقسات وتفعل هي في الاسطقسات أيضاً<\/span>","st":"28"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيحدث من اجتماع هذه الافعال بجهات مختلفة اختلاطات أخر كثيرة تبعد بها عن الاسطقسات والمادة الأولى بعداً كثيراً ولا تزال تختلط اختلاطاً بعد اختلاط قبله فيكون الاختلاط الثاني أبداً أكثر تركيباً مما قبله الى أن تحدث أجسام لا يمكن أن تختلط فيحدث من اختلاطها جسم آخر أبعد منها عن الاسطقسات فيقف الاختلاط ،<\/span>","st":"29"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فبعض الاجسام يحدث عن الاختلاط الاول . وبعضها عن الثاني . وبعضها عن الثالث . وبعضها عن الاختلاط الآخر ،<\/span>","st":"29"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمعدنيات تحدث باختلاط أقرب الى الاسطقسات وأقل تركيباً ويكون بعدها عن الاسطقسات برتب أقل . ويحدث النبات باختلاط أكثر منها تركيباً وأبعد عن الاسطقسات برتب أكثر . والحيوان غير الناطق يحدث باختلاط أكثر تركيباً من النبات . والانسان وحده هو الذي يحدث عن الاختلاط الاخير<\/span>","st":"29"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويحدث في كل واحد من هذه الانواع قوي يتحرك بها من تلقاء نفسه وقوى يفعل بها في غيره وقوى يقبل بها فعل غيره فيه والفاعل منها في غيره . فموضوعات فعله ثلاثة بالجملة منها ما يفعل فيه على الاكثر . ومنها ما يفعل فيه على الاقل ومنها ما يفعل فيه على التساوي وكذلك القابل لفعل غيره قد يكون موضوعاً لثلاثة أصناف من الفاعلات لما هو فاعل فيه على الاكثر . ولما هو فاعل فيه على الاقل . ولما هو فاعل فيه على التساوي .<\/span>","st":"29"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وفعل كل واحد في كل واحد اما بأن يرفده واما بأن يضاده .<\/span>","st":"29"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم الاجسام السماوية تفعل في كل واحد منها مع فعل بعضه في بعض بأن ترفد بعضها وتضاد بعضها . وما ترفده فانه ترفده حيناً وتضاده حيناً . وما تضاده فانه تضاده حيناً وترفده أيضاً حيناً آخر فتقترن أصناف الافعال السماوية فيها الى أفعال بعضها في بعض فيحدث من اقترانها امتزاجات واختلاطات أخر كثيرة جداً يحدث في كل نوع أشخاص كثيرة مختلفة جداً<\/span>","st":"29"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فهذه هي أسباب وجود الاشياء الطبيعية التي تحت السماوية ،<\/span>","st":"30"},{"sp":"HDR","t":"القول في تعاقب الصور على الهيولى"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وعلى هذه الجهات يكون وجودها أولاً فاذا وجدت فسبيلها أن تبقى وتدوم . ولكن لما كان هذا حاله من الموجودات قوامه من مادة وصورة وكانت الصورة متضادة . وكل مادة فان شأنها أن توجد لها هذه الصورة وضدها فصار لكل واحد من هذه الاجسام حق واستئهال بصورته وحق واستئهال بمادته فالذي يحق صورته أن يبقى على الوجود الذي له والذي يحق له بحق مادته أن يوجد وجوداً آخر مضادة للوجود الذى هو له واذا كان لا يمكن أن يوفى هذين معا فى وقت واحد . لزم ضرورة أن يوفى هذا مرة فيوجد ويبقى مدة ما محفوظ الوجود ثم يتلف ويوجد ضده ثم يبقى ذلك وكذلك أبداً فانه ليس وجود أحدهما أولى من وجود الآخر ولا بقاء أحدهما أولى من بقاء الآخر . اذ كان لكل واحد منهما قسما من الوجود والبقاء،<\/span>","st":"30"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فان المادة الواحدة لما كانت مشتركة بين ضدين وكان قوام كل واحد من الضدين بها ولم تكن المادة أولى بأحد الضدين دون الآخر ولم يمكن أن تجعل لكلاهما فى وقت واحد لزم ضرورة أن تعطى تلك المادة أحيانا هذا الضد وأحيانا ذلك الضد ويعاقب بينهما<\/span>","st":"30"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيصير كل واحد منهما كأنّ له حقا عند الآخر . ويكون عنده شئ مالغيره وعند غيره شئ هو له فعند كل واحد منهما حق ما ينبغي أن يصير الى كل واحد من كل واحد . فالعدل فى هذا أن يوجد مادة هذا فيعطى ذلك أو يوجد مادة ذلك فيعطى هذا ويعاقب ذلك بينهما فلأجل الحاجة الى توفية العدل فى هذه الموجودات لم يمكن أن يبقى الشئ الواحد دائما على أنه واحد بالعدد فجعل بقاءه الدهر كلها على أنه واحد بالنوع ويحتاج في أن يبقى الشئ واحداً بالنوع الى أن يوجد أشخاص ذلك النوع مدة ما ثم تتلف ويقوم مقامها أشخاص أخر من ذلك النوع . وذلك على هذا المثال دائماً<\/span>","st":"30"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه منها ما هي اسطقسات . ومنها ما هي كائنة عن اختلاطها . والتي هي عن اختلاطها منها ما هي عن اختلاط أكثر تركيباً ومنها ما هي عن اختلاط أقل تركيباً . وأما الاسطقسات فان المضاد المتلف لكل واحد منها هي من خارج فقط اذ كان لا ضد له في جملة جسمه . وأما الكائن عن اختلاط قليل تركيباً فان المضادات التي فيها يسيرة وقواها منكسرة ضعيفة . فلذلك صار المضاد المتلف له في ذاته ضعيف القوة لا يتلفه الا بمعنى من خارج فصار المضاد المتلف له أيضاً من خارج . وما هو كائن عن اختلاط أقل تركيباً فان المضادات المتلفة له هي من خارج فقط والتي هي عن اختلاط أكثر تركيباً . فبكثرة المتضادات التي فيها وتراكيبها يكون تضادها فيها في الاشياء المختلطة أظهر وقوى المتضادات التي فيها قوية ويفعل بعضها مع بعض معاً أيضاً فانها لما كانت من أجزاء غير متشابهة . لم يمتنع أن يكون فيها تضاد فيكون المضاد المتلف له من خارج جسمه ومن داخله معا .<\/span>","st":"31"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وما كان من الاجسام يتلفه المضاد له من خارج فانه لا يتحلل من تلقاء نفسه دائما مثل الحجارة والرمل فان هذين وما جانسهما انما يتحللان من الاشياء الخارجة فقط . واما الآخر من النبات والحيوان فانهما يتحللان أيضاً من أشياء مضادة لهما من داخل فلذلك ان كان شيء من هذه مزمنًا تبقى صورته مدة مابان يخلف بدل ما يتحلل من جسمه دائماً . وانما يكون ذلك الشيء يقوم مقام ما يتحلل ولا يمكن ان يخلف شيء بدل ما يتحلل من جسمه ويتصل بذلك الجسم الا فيخلع عن ذلك الجسم صورته التي كانت له ويكتسي صورة هذا الجسم بعينه وذلك هو أن يتغذى حيث جعلت في هذه الاجسام قوة غاذية . وكل ما كان معيناً لهذه القوة حتى صار كل جسم من هذه الاجسام يجتذب الى نفسه شيئاً ما مضادا له فتنسلخ عنه تلك الضدية ويقبله بذاته ويكسوه الصورة التي هو ملتحف بها الى ان تجوز هذه القوة في طول المدة فيتحلل من ذلك جسم مالم يمكن القوة الجابرة ان ترد مثله فيتلف ذلك الجسم فيه فبهذا الوجه حفظ من محلله الداخل . وأما من متلفه الخارج فانه حفظ بالآلات التي جعلت له بعضها فيه وبعضها من خارج جسمه فيحتاج في دوام ما يدوم واحداً بالنوع الى أن يقوم مقام من تلف منه أشخاص أخر تقوم مقام ما تلف منها<\/span>","st":"31"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويكون ذلك . اما ان يكون مع الاشخاص الاول اشخاص أحدثت وجوداً منها حتى اذا تلف تلك الاول قامت هذه مقامها حتى لا يخلو في كل وقت من الاوقات وجود شخص ما من ذلك النوع . ما في ذلك المكان أو في مكان آخر . واما ان يكون الذي يخلف الاول يحدث بعد زمان ما من تلف الاول حتى يخلو زمان ما من غير أن يوجد فيه شئ من أشخاص ذلك النوع . فجعل في بعضها قوى يكون بها شبيهه في النوع ولم تجعل في بعض .<\/span>","st":"32"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وما لم يجعل فيها فان أسباب ما يتلف منه تكونه الاجسام السماوية وحدها اذ هي مرافدة للاسطقسات له على ذلك . وما جعل فيه قوة يكون بها شبيهه في النوع فعلى تلك القوة التي له ويقترن الى ذلك فعل الاجسام السماوية . وسائر الاجسام الاخر . أما بان تفيد . واما بان تضاد مضادة لا تبطل فعل القوة بل تحدث امتزاجا إما أن يعتدل به الفعل الكائن بتلك القوة وإما ان يزيله عن الاعتدال قليلا أو كثيراً بمقدار مالا يبطل فعله فيحدث عند ذلك ما يقوم مقام التالف من ذلك النوع . وكل هذه الاشياء إما على الاكثر واما على الاقل واما على التساوى فبهذا الوجه يدوم بقاء هذا الجنس من الموجودات<\/span>","st":"32"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكل واحد من هذه الاجسام له حق واستئهال بصورته وحق واستئهال بمادته فالذي له بحق صورته أن يبقى على الوجود الذى له ولا يزول والذى له بحق مادته هو أن يجد وجوداً آخر مقابلا مضاداً للوجود الذى هو له والعدل أن يوفى كل واحد منهما استئهاله واذ لا يمكن توفيته اياه فى وقت واحد لزم ضرورة أن يوفى هذا مرة وذلك مرة فيوجد ويبقى مدة ما محفوظ الوجود ويتلف ويجد ضده وذلك أبداً.<\/span>","st":"33"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والذى يحفظ وجوده اما قوة فى الجسم الذى فيه صورته. واما قوة فى جسم آخر هي آلة مقارنة له تخدمه فى حفظ وجوده. واما أن يكون المتولى بحفظه جسم ما آخر يرأس المحفوظ وهو الجسم السمائى أو جسم ما غيره. واما ان يكون ذلك باجتماع هذه كلها<\/span>","st":"33"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأيضاً فان هذه الموجودات لما كانت متضادة كانت مادة كل ضدين منها مشتركة. فالمادة التى لهذا الجسم هي أيضاً بعينها مادة لذلك والتى لذلك هي أيضاً بعينها لهذا فعند كل واحد منهما شيء هو لغيره وعند غيره شيء هو له فيكون كأن لكل واحد عند كل واحد من هذه الجهة حقاً ما ينبغي أن يصير الى كل واحد من كل واحد والمادة التى تكون للشئ عند غيره. واما مادة سبيلها أن تكتسى صورة ذلك بعينها مثل الجسم الذى يغتذى بجسم آخر. وأما مادة سبيلها ان تكتسي صورة نوعه لا صورته بعينها مثل ناس يخلفون ناساً مضوا.<\/span>","st":"33"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والعدل في ذلك ان يجد ما عند هذا من مادة ذلك فيعطي ذلك وما عند ذلك من مادة هذا فيعطي ذلك هذا. والذى به يستوفي الشئ مادته من ضده وينتزع به تلك منه. اما ان يكون قوة فيه مقترنة بصورته في جسم واحد فيكون ذلك الجسم آلة له في هذا غير مفارقة واما ان يكون في جسم آخر فيكون ذلك آلة له مفارقة تخدمه في أن ينتزع مادة من ضده فقط وتكون قوة أخرى في ذلك الجسم أو في آخر تكسوه. اما صورته بعينها واما صورة نوعه واما ان تكون قوة واحدة تفعل الامرين جميعاً. واما ان تكون التى تكون تستوفي له حقه جسم آخر برأسه. اما سمائية أو غيرها. واما ان يكون ذلك باجتماع هذه كلها.<\/span>","st":"33"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والجسم انما يكون مادة للجسم الآخر. أما بان يوفيه صورته على التمام. واما بان يكسوه من صورته وينقص من عزته. والذى يكون له آلة تخدم جسماً آخر فانما يكون آلة بأحد هذين أيضاً. وذلك اما بصورته على التمام واما بان يكسوه قليلاً من عزة صورته مقدار مالا يخرجه ذلك من ماهيته مثل ما يكسوا من ذراعهم العبد ويقمعهم حتى يذلوا فيخدموا.<\/span>","st":"34"},{"sp":"HDR","t":"القول في أجزاء النفس الانسانية وقواها"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذ حدث الانسان فاول ما يحدث فيه القوة التي بها يتغذى وهي القوة الغاذية ثم من بعد ذلك القوة التي بها يحس الملموس مثل الحرارة والبرودة وسائرها التي بها يحس الطعوم والتي بها يحس الروائح والتي بها يحس الاصوات والتي بها يحس الالوان والمبصرات كلها مثل الشعاعات ويحدث مع الحواس بها نزاع الى ما يحسه فيشتاقه أو يكرهه ثم يحدث فيه بعد ذلك قوة أخرى يحفظ بها ما رسم في نفسه من المحسوسات بعد غيبتها عن مشاهدة الحواس لها. وهذه هي القوة المتخيلة فهذه تركب المحسوسات بعضها الى بعض وتفصل بعضها عن بعض تركيبات وتفصيلات مختلفة بعضها كاذبة وبعضها صادقة ويقترن بها نزاع نحو ما يتخيله<\/span>","st":"34"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم من بعد ذلك يحدث فيه القوة الناطقة التي بها يمكن أن يعقل المعقولات وبها يميز بين الجميل والقبيح وبها يحوز الصناعات والعلوم ويقترن به أيضاً نزاع نحو ما يعقله ،<\/span>","st":"34"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالقوة الغاذية منها قوة واحدة رئيسة ومنها قوى هي رواضع ولخدم . فالقوة الغاذية الرئيسة هي من أعضاء البدن في الفم . والرواضع والخدم متفرقة في سائر الاعضاء وكل قوة من الرواضع والخدم فهي في عضو ما من سائر أعضاء البدن .<\/span>","st":"35"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والرئيسة منها هي بالطبع مدبرة لسائر القوي وسائر القوى يشبه بها ويحتذى بأفعالها حذو ما هو بالطبع غرض رئيسها الذي في القلب .<\/span>","st":"35"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك مثل المعدة والكبد والطحال والاعضاء الخادمة هذه والاعضاء التي تخدم هذه الخادمة والتي تخدم هذه أيضاً فان الكبد عضو يرؤس ويرأس فانه يرأس بالقلب ويرؤس بالمرارة والكلية وأشباههما من الاعضاء والمثانة تخدم الكلية . والكلية تخدم الكبد . والكبد يخدم القلب وعلى هذا توجد سائر الاعضاء .<\/span>","st":"35"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والقوة الحاسة فيها رئيس وفيها رواضع . ورواضعها هي هذه الحواس الخمس المشهورة عند الجميع المتفرقة في العينين وفي الاذنين وفي سائرها . وكل واحد من هذه الخمس يدرك حساً ما يخصه . والرئيسة منها هي التي اجتمع فيها جميع ما تدركه الخمس بأسرها وكأن هذه الخمس هي منذرات تلك وكان هؤلاء أصحاب اخبار وكل واحد منهم موكل بجنس من الاخبار وباخبار ناحية من نواحي المملكة . والرئيسة كأنها هي الملك الذي عنده تجتمع أخبار نواحي مملكته من أصحاب أخباره والرئيسة من هذه أيضاً هي في القلب .<\/span>","st":"35"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والقوة المتخيلة ليس لها رواضع متفرقة في أعضاء أخر بل هي واحدة وهي أيضاً في القلب وهي تحفظ المحسوسات بعد غيبتها عن الحس وهي بالطبع حاكمة على المحسوسات ومتحكمة عليها وذلك انها تفرد بعضها عن بعض وتركب بعضها الى بعض تركيبات مختلفة يتفق في بعضها أن تكون موافقة لما حس وفي بعضها أن تكون مخالفة للمحسوس<\/span>","st":"35"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأما القوة الناطقة فلا رواضع ولا خدم لها من نوعها في سائر الاعضاء بل انما رئاستها على سائر القوى المتخيلة . والرئيسة من كل جنس فيه رئيس ومرؤوس فهي رئيسة القوة المتخيلة ورئيسة القوة الحاسّة الرئيسة منها . ورئيسة القوة الغاذية الرئيسة منها<\/span>","st":"35"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والقوة النزوعية وهي التي تشتاق الى الشئ وتكرهه فهي رئيسة ولها خدم . وهذه القوة هي التي بها تكون الارادة فان الارادة هي نزوع الى ما أدرك وعن ما أدرك . اما بالحس . واما بالتخيل واما بالقوة الناطقة . وحكم فيه أنه ينبغي أن يؤخذ أو يترك<\/span>","st":"36"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والنزوع قد يكون الى علم شيءٍ ما وقد يكون الى عمل شيءٍ ما اما بالبدن بأسره واما بعضوٍ ما منه . والنزوع انما تكون بالقوة النزوعية الرئيسة . والاعمال بالبدن تكون بقوى تخدم القوة النزوعية وتلك القوة متفرقة في أعضاء أعدت لأن يكون بها تلك الافعال . منها أعصاب ومنها عضل سارية في الاعضاء التي تكون بها الافعال التي نزوع الحيوان والانسان اليها . وتلك الاعضاء مثل اليدين والرجلين وسائر الاعضاء التي يمكن أن تتحرك بالارادة . فهذه القوى التي في أمثال هذه الاعضاء هي كلها آلات جسمانية وخادمة للقوى النزوعية الرئيسة التي في القلب .<\/span>","st":"36"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وعلم الشيء قد يكون بالقوة الناطقة وقد يكون بالمتخيلة وقد يكون بالاحساس . فاذا كان النزوع الى علم شيءٍ شأنه أن يدرك بالقوة الناطقة فان الفعل الذي ينال به ما تشوق من ذلك يكون قوة ما أخرى في الناطقة وهي القوة الفكرية وهي التي تكون بها الفكرة والرؤية والتأمل والاستنباط . واذا كان النزوع الى علم شيءٍ ما يدرك باحساس . كان الذي ينال به فعل مركب من فعل بدني ومن فعل نفساني في مثل الشيء الذي نتشوق رؤيته فانه يكون برفع الاجفان وبأن نحاذي ابصارنا نحو الشئ الذي نتشوق رؤيته. فان كان الشئ بعيداً مشينا اليه وان كان دونه حاجز أزلنا بأيدينا ذلك الحاجز فهذه كلها أفعال بدنية والاحساس بنفسه فعل نفساني وكذلك في سائر الحواس<\/span>","st":"36"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واذا تشوق تخيل شئ ما نيل ذلك من وجوه . أحدها فعل بالقوة المتخيلة مثل تخيل الشئ الذي يرجى ويتوقع أو تخيل شئ مضى . أو تمنى شئ ما تركته القوة المتخيلة . والثاني ما يرد على القوة المتخيلة من احساس شئ ما فتخيل اليه من ذلك أمر ما انه مخوف أو مأمول . أو ما يرد عليه من فعل القوة الناطقة فهذه القوى النفسانية<\/span>","st":"37"},{"sp":"HDR","t":"القول كيف تصير هذه القوى والاجزاء نفساً واحدة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالغاذية الرئيسة شبه المادة للقوة الحاسة الرئيسة. والحاسة صورة في الغاذية. والحاسة الرئيسة شبه مادة للمتخيلة. والمتخيلة صورة في الحاسة الرئيسة. والمتخيلة الرئيسة مادة للناطقة الرئيسة والناطقة صورة في المتخيلة وليست مادة لقوى أخرى فهي صورة لكل صورة تقدمتها . وأما النزوعية فانها تابعة للحاسة الرئيسة والمتخيلة والناطقة على جهة ما توجد الحرارة في النار تابعة لما تتجوهر به النار .<\/span>","st":"37"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالقلب هو العضو الرئيس الذي لا يرأسه من البدن عضو آخر . ويليه الدماغ فانه أيضاً عضو ما رئيس ورئاسته ليست رئاسة أولية لكن رئاسة ثانية وذلك لانه يرأس بالقلب ويرأس سائر الاعضاء فانه يخدم القلب في نفسه وتخدمه سائر الاعضاء بحسب ما هو مقصود القلب بالطبع وذلك مثل صاحب دار الانسان فانه يخدم الانسان في نفسه وتخدمه سائر أهل داره بحسب ماهو مقصود الانسان في الامرين كانه يخلفه ويقوم مقامه وينوب عنه ويتبدل فيما ليس يمكن أن يبدله الرئيس وهو المستولى على خدمة القلب في الشريف من أفعاله .<\/span>","st":"37"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">من ذلك ان القلب ينبوع الحرارة الغريزية فمنه تنبث في سائر الاعضاء ومنه تسترفد وذلك بما ينبث فيها عنه من الروح الحيواني الغريزي في العروق الضوارب ومما يرفدها القلب من الحرارة انما تبقى الحرارة الغريزية محفوظة على الاعضاء . والدماغ هو الذي يعدل الحرارة التي شأنها أن تنفذ اليه من القلب حتى يكون ما يصل الى كل عضو من الحرارة معتدلاً ملائماً له وهذا أول أفعال الدماغ وأول شئ يخدم به . وأعم اللأعضاء<\/span>","st":"37"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومن ذلك أن في الاعصاب صنفين أحدهما آلات لمواضع القوة الحاسة الرئيسة التي في القلب في أن يحس كل واحد منها الحس الخاص به . والآخر آلات الاعضاء التي تخدم القوة النزوعية التي في القلب بها يتأتى لها أن تحرك الحركة الارادية . والدماغ يخدم القلب في أن يرفد اعصاب الحس ما يبقى به قواها التي بها يتأتى للرواضع أن تحس محفوظة عليها . والدماغ أيضاً يخدم القلب في أن يرفد أعصاب الحركة الارادية ما يبقى به قواها التي بها يتأتى للاعضاء الآلية الحركة الارادية التي تخدم بها القوة النزوعية التي في القلب .<\/span>","st":"38"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان كثيراً من هذه الاعصاب مغارزها التي منها يستمر قدما يحفظ به قواها في الدماغ نفسه . وكثيراً منها مغارزها في النخاع النافذ والنخاع من أعلاه متصل بالدماغ فان الدماغ يرفدها بمشاركة النخاع لها في الارفاد .<\/span>","st":"38"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومن ذلك ان تخيل القوة المتخيلة انما يكون متى كانت حرارة القلب على مقدار محدود . وكذلك فكر القوة الناطقة انما يكون متى كانت حرارته على ضرب ما من التقدير أي فعل وكذلك حفظها وتذكرها للشئ .<\/span>","st":"38"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالدماغ أيضاً يخدم القلب بان يجعل حرارته على الاعتدال الذي يجود به تخيله وعلى الاعتدال الذي يجود به فكره ورويته وعلى الاعتدال الذي يجود به حفظه وتذكره فبجزء منه يعدل به ما يصلح به التخيل وبجزء آخر منه يعدل به ما يصلح به الفكر وبجزء ثالث يعدل به ما يصلح الحفظ والذكر .<\/span>","st":"38"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك ان القلب لما كان ينبوع الحرارة الغريزية لم يمكن أن يجعل الحرارة التي فيه الاقوية مفرطة ليفضل منه ما يفيض الى سائر الاعضاء ولئلا يقصر أو يجود فلم تكن كذلك في نفسها الا لغاية بقلبه . فلما كان كذلك وجب أن يعدل حرارته التي تنفذ الى الاعضاء ولا تكون حرارته في نفسها على الاعتدال الذى يجود به أفعاله التي تخصه . فجعل الدماغ لاجل ذلك بالطبع باردا رطباً حتى في الملمس بالاضافة الى سائر الاعضاء وجعلت فيه قوة نفسانية تصير بها حرارة القلب على اعتدال محدود محصل ،<\/span>","st":"38"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والاعصاب التي للحس والتي للحركة لما كانت أرضية بالطبع سريعة القبول للجفاف كانت تحتاج الى ان تبقى رطبة الى لدانة مؤاتية للتمدد والتقاصر . وكانت اعصاب الحس محتاجة مع ذلك الى الروح الغريزي الذي ليست فيه دخانية اصلاً . وكان الروح الغريزي السالك في أجزاء الدماغ هذه حاله ،<\/span>","st":"39"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولما كان القلب مفرط الحرارة ناريها لم يجعل مغارزها التي بها يسترفد ما يحفظ قواها في القلب . لئلا يسرع الجفاف اليها فتتحلل وتبطل قواها . وأفعالها جعلت مغارزها في الدماغ وفي النخاع لانهما رطبان جداً لتنفذ من كل واحد منهما في الاعصاب رطوبة تبقيها على اللدونة وتستبقي بها قواها النفسانية .<\/span>","st":"39"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فبعض الاعصاب يحتاج فيها الى أن تكون الرطوبة النافذة فيها مائية لطيفة غير لزجة أصلا وبعضها محتاج فيها الى لزوجة ما . فما كان منها محتاجا الى مائية لطيفة غير لزجة جعلت مغارزها في الدماغ . وما كان منها محتاجا فيها مع ذلك الى أن تكون رطوبتها فيها لزوجة جعلت مغارزها في النخاع . وما كان منها محتاجا فيها الى أن تكون رطوبتها قليلة جعلت مغارزها أسفل الفقار والعصعص ،<\/span>","st":"39"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم بعد الدماغ الكبد وبعده الطحال وبعد ذلك أعضاء التوليد وكل قوة في عضو كان شأنها ان تفعل فعلا جسمانياً ينفصل به من ذلك العضو جسم ما ويصير الى آخر . فانه يلزم ضرورة . اما ان يكون ذلك الآخر متصلا بالاول مثل اتصال كثير من الاعصاب بالدماغ وكثير منها بالنخاع . أو ان يكون له طريق ومسيل متصل لذلك العضو يجرى فيه ذلك الجسم وكانت تلك القوة خادمة له . أو رئيسة مثل الفم والرئة والكلية والكبد والطحال وغير ذلك . وكلما احتاجت أو كان شأنها ان تفعل فعلاً نفسانياً في غيره ثم يلزم ضرورة ان يكون بينهما مسيل جسماني مثل فعل الدماغ في القلب ، فاول ما يتكون من الاعضاء القلب ثم الدماغ ثم الكبد ثم الطحال ثم تتبعها سائر الاعضاء<\/span>","st":"39"},{"sp":"HDR","t":"XXIb. The Organs of Generation"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واعضاء التوليد متأخرة الفعل من جميعها . ورياستها في البدن يسيرة مثل ما يتبين من فعل الانثيين وحفظهما الحرارة الذكرية والروح الذكرى السائفين من القلب في الحيوان الذكر الذي له انثيان ،<\/span>","st":"40"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والقوة التي بها يكون التوليد منها رئيسة ومنها خادمة . والرئيسة منها في القلب . والخادمة في أعضاء التوليد والقوة التي يكون بها التوليد اثنتان احداهما تعد المادة التي يتكون عنها الحيوان الذي له تلك القوة والأخرى تعطي صورة ذلك النوع من الحيوان وتحرك المادة الى أن تحصل لهاتلك الصورة التي لذلك النوع . والقوة التي تعد المادة هي قوة الانثى . والتي تعطي الصورة هي قوة الذكر .<\/span>","st":"40"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان الانثى هي انثي بالقوة التي تعد بها المادة . والذكر هو ذكر بالقوة التي تعطي تلك المادة صورة ذلك النوع الذي له تلك القوة والعضو الذي يخدم القلب في ان يعطي مادة الحيوان هو الرحم والذى يخدمه في ان يعطى الصورة اما في الانسان واما في غيره من الحيوان العضو الذى يكوّن المني فان المني اذا ورد على رحم الانثى فصادف هناك دما قد أعده الرحم لقبول صورة الانسان . أعطى المني ذلك الدم قوة تتحرك بها الى ان يحصل من ذلك الدم أعضاء الانسان وصورة كل عضو وبالجملة صورة الانسان . فالدم المعد في الرحم هو مادة الانسان والمني هو المحرك لتلك المادة الى أن تحصل فيها الصورة .<\/span>","st":"40"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومنزلة المني من الدم المعد في الرحم منزلة الانفحة التي ينعقد عنها اللبن وكما ان الانفحة هي الفاعلة للانعقاد في اللبن وليس هي جزأ من المنعقد ولا مادةً . كذلك المني ليس هو جزأ من المنعقد في الرحم ولا مادة<\/span>","st":"40"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والجنين يتكوّن عن المني كما يتكون الرائب من الانفحة . ويتكون عن دم الرحم كما يتكون الرائب عن اللبن الحليب . والابريق عن النحاس والذى يكوّن المني في الانسان هي الاوعية التي يوجد فيها المني . وهي العروق التي تحت جلد العانة . يرفدها في ذلك بعض الارفاد الانثيان وهذه العروق نافذة الى المجرى الذى في القضيب ليسيل من تلك العروق الى مجرى القضيب ويجرى في ذلك المجرى الى أن ينصبّ في الرحم ويعطى الدم الذي فيه مبدأ قوة يتغير بها الى أن تحصل به الاعضاء . وصورة كل عضو . وصورة جملة البدن<\/span>","st":"41"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمنى آلة الذكر . والآلات منها مواصلة ومنها مفارقة من ذلك . مثل الطبيب فان اليد آلة للطبيب يعالج بها والمبضع آلة له يعالج بها . والدواء آلة له يعالج بها فالدواء آلة مفارقة وانما يواصله الطبيب حين ما يفعله ويصنعه ويعطيه قوة يحرك بها بدن العليل الى الصحة فاذا حصلت فيه تلك القوة ألقاها في جوف بدن العليل مثلا فتحرك بدنه نحو الصحة . والطبيب الذي القاها غائب أو ميت مثلا . وكذلك منزلة المنى<\/span>","st":"41"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمبضع لا تفعل فعلها الا بمواصلة الطبيب المستعمل له . واليد أشد مواصلة له من المبضع . وأما الدواء فانه يفعل بالقوة التي فيه من غير أن يكون الطبيب مواصلا له . كذلك المنى فانه آلة للقوة المولدة الذكرية وتفعل مفارقة . وأوعية المنى والانثيان آلة للتوليد مواصلة للبدن .<\/span>","st":"41"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فمنزلة العروق التي تكون آلات المني من القوة الرئيسة التي في القلب منزلة يد الطبيب التي يعمل بها الدواء ويعطيه قوة محركة بها بدن العليل الى الصحة فان تلك العروق التي يستعملها القلب بالطبع . هي آلات في أن يعطى المنى القوة التى يحرك بها الدم المعد في الرحم الي صورة ذلك النوع من الحيوان . فاذا أخذ الدم عن المنى القوة التى يتحرك بها الى الصورة فأول ما يتكون القلب وينتظر بتكوينه تكوين سائر الاعضاء ما يشق أن يحصل في القلب من القوي<\/span>","st":"41"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان حصلت فيه مع القوة الغاذية القوة التى بها تعد المادة تكون سائر الاعضاء على انها أعضاء أنثي . فان حصلت فيه القوة التى تعطى الصورة تكون سائر الاعضاء على انها أعضاء ذكر فتحصل من تلك الاعضاء المولدة التى للانثى . وتحصل من هذه الاعضاء المولدة التى للذكر . ثم سائر القوي النفاسية الباقية تحدث في الأنثى على مثال ما هي في الذكر .<\/span>","st":"42"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهاتان القوتان أعنى الذكرية والانثوية هما في الانسان مفترقان في شخصين وأما في كثير من النبات فانهما مقترنان علي التمام في شخص واحد . مثل كثير من النبات الذى يتكون عن البذر فان النبات يعطي المادة وهي البذر ويعطى بها مع ذلك قوة يتحرك بها نحو الصورة . فان البذر فيه استعداد لقبول الصورة وقوة يتحرك بها نحو الصورة . فالذى أعطاه الاستعداد لقبول الصورة هي القوة الانثوية والذى أعطاه مبدأ يتحرك به نحو الصورة . هو القوة الذكرية . وقد يوجد أيضاً في الحيوان ما سبيله هذا السبيل ويوجد أيضاً ما القوة الانثوية فيه تامة وتقترن اليها قوة مذكرة ناقصة تفعل فعلها الى مقدار ما ثم تجوز فتحتاج الى معين من خارج مثل الذي يبيض بيض الريح ومثل كثير من أجناس السمك التي تبيض ثم تودع بيضها فيتبعها ذكورتها فتلقي رطوبة فأية بيضة أصابها من تلك الرطوبة شيء كان عنها حيوان . وما لم يصبها ذلك فسدت ،<\/span>","st":"42"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأما الانسان فليس كذلك . بل هاتان القوتان متميزتان في شخصين . ولكل واحد منهما أعضاء تخصه وهي الاعضاء المعروفة وسائر الاعضاء فيهما مشترك كان . وكذلك يشتركان في قوى النفس كلها سوى هاتين . وما يشترك فيه من أعضاء فانه في الذكر أسخن . وما كان منها فعله الحركة والتحريك فانه في الذكر أقوى حركة وتحريكاً .<\/span>","st":"42"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والعوارض النفسانية فما كان منها مائلاً الى القوة مثل الغضب والقسوة فانها في الانثى أضعف وفي الذكر أقوى . وما كان من العوارض مائلة الى الضعف مثل الرأفة والرحمة فانه في الانثى أقوى . على انه لا يمتنع أن يكون في ذكورة الانسان من توجد العوارض فيه شبيهة بما في الاناث وفي الاناث من توجد فيه هذه شبيهة بما هو في الذكور . فبهذه تفترق الاناث والذكور في الانسان، واما في القوة الحاسّة وفي المتخيلة وفي الناطقة فليس يختلفان<\/span>","st":"43"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فيحدث عن الاشياء الخارجة رسوم المحسوسات في القوي الحاسّة التي هي رواضع ثم تجتمع المحسوسات المختلفة الاجناس المدركة بانواع الحواس الخمسة في القوى الحاسّة الرئيسة ويحدث عن المحسوسات الحاصلة في هذه القوي رسوم المتخيلات في القوة المتخيلة فتبقى هناك محفوظة بعد غيبتها عن مباشرة الحواس لها فيتحكم فيها فيفرد بعضها عن بعض أحيانا ويركب بعضها الى بعض أصنافا من التركيبات كثيرة بلا نهاية بعضها كاذبة وبعضها صادقة .<\/span>","st":"43"},{"sp":"HDR","t":"القول في القوة الناطقة كيف تعقل وما سبب ذلك"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويبقي بعد ذلك ان ترسم في الناطقة رسوم اصناف المعقولات . والمعقولات التي شأنها ان ترسم في القوة الناطقة منها المعقولات التي هي في جواهرها عقول بالفعل . ومعقولات بالفعل وهي الاشياء البريئة من المادة . ومنها المعقولات التي ليست بجواهرها معقولة بالفعل مثل الحجارة والنبات وبالجملة كل ماهو جسم او فى جسم ذى مادة والمادة نفسها وكل شئ قوامه بها. فان هذه ليست عقولا بالفعل ولا معقولات بالفعل<\/span>","st":"43"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واما العقل الانسانى الذى يحصل له بالطبع فى اول أمره. فانه هيئة ما فى مادة معدة لأن تقبل رسوم المعقولات فهى بالقوة عقل وعقل هيولانى. وهى أيضاً بالقوة معقولة وسائر الاشياء التى فى مادة. او هى مادة او ذوات مادة فليست هى عقولا لا بالفعل ولا بالقوة ولكنها معقولات بالقوة ويمكن ان تصير معقولات بالفعل. وليس فى جواهرها كفاية فى ان تصير من تلقاء نفسها معقولات بالفعل. ولا أيضاً فى القوة الناطقة. ولا فيما اعطى الطبع كفاية فى أن تصير من تلقاء نفسها عقلا بالفعل بل تحتاج ان تصير عقلا بالفعل الى شئ آخر ينقلها من القوة الى الفعل. وانما تصير عقلا بالفعل اذا حصلت فيها المعقولات وتصير المعقولات التى بالقوة معقولات بالفعل اذا حصلت معقولة للعقل بالفعل. وهى تحتاج الى شئ آخر ينقلها من القوة الى ان يصيرها بالفعل.<\/span>","st":"44"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والفاعل الذى ينقلها من القوة الى الفعل. هو ذات ما جوهره عقل ما بالفعل ومفارق المادة فان ذلك العقل يعطى العقل الهيولانى الذى هو بالقوة عقل شيئاً بمنزلة الضوء الذى تعطيه الشمس البصر . لان منزلته من العقل الهيولانى منزلة الشمس من البصر . فان البصر هو قوة وهيئة ما فى مادة وهو من قبل ان يبصر فيه بصر بالقوة والالوان من قبل ان تبصر مبصرة مرئية بالقوة .<\/span>","st":"44"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وليس فى جوهر القوة الباصرة التى فى العين كفاية فى ان يصير بصرا بالفعل . ولا فى جواهر الالوان كفاية فى ان تصير مرئية مبصرة بالفعل . فان الشمس تعطى البصر ضوءاً يضاء به وتعطى الالوان ضوءاً يضاء بها . فيصير البصر بالضوء الذى استفاده من الشمس مبصرا بالفعل وبصيرا بالفعل . وتصير الالوان بذلك الضوء مبصرة مرئية بالفعل بعد ان كانت مبصرة مرئية بالقوة .<\/span>","st":"44"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">كذلك هذا العقل الذى بالفعل يفيد العقل الهيولانى شيئاً ما يرسمه فيه فمنزلة ذلك الشئ من العقل الهيولانى منزلة الضوء من البصر وكما ان البصر بالضوء نفسه يبصر الضوء الذى هو سبب أبصاره ويبصر الشمس التى هى سبب الضوء به بعينه ويبصر الاشياء التى هى بالقوة مبصرة فتصير مبصرة بالفعل كذلك العقل الهيولانى فانه بذلك الشئ الذى منزلته منه منزلة الضوء من البصر يعقل ذلك الشئ نفسه وبه يعقل العقل الهيولانى العقل بالفعل الذى هو سبب ارتسام ذلك الشئ فى العقل الهيولانى وبه تصير الاشياء التى كانت معقولة بالقوة معقولة بالفعل ويصير هو أيضاً عقلا بالفعل بعد أن كان عقلا بالقوة . وفعل هذا العقل المفارق فى العقل الهيولانى شبيه فعل الشمس فى البصر فلذلك سمى العقل الفعال ومرتبته فى الاشياء المفارقة التى ذكرت من دون السبب الاول المرتبة العاشرة ويسمى العقل الهيولانى العقل المنفعل<\/span>","st":"44"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واذا حصل فى القوة الناطقة عن العقل الفعال ذلك الشئ الذى منزلته منها منزلة الضوء من البصر . حصلت المحسوسات حينئذ عن التى هى محفوظة فى القوة المتخيلة معقولات فى القوة الناطقة وتلك هى المعقولات الاولى التى هى مشتركة لجميع الناس مثل ان الكل أعظم من الجزء وان المقادير المساوية للشئ الواحد متساوية<\/span>","st":"45"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">المعقولات الاولى المشتركة ثلاثة أصناف . صنف أوائل للهندسة العلمية . وصنف أوائل يوقف بها على الجميل والقبيح مما شأنه أن يعمله الانسان . وصنف أوائل يستعمل فى أن يعلم بها أحوال الموجودات التى ليس شأنها أن يفعلها الانسان ومباديها ومراتبها مثل السموات والسبب الأول وسائر المبادى الأخر وما شأنها أن يحدث عن تلك المبادى ،<\/span>","st":"45"},{"sp":"HDR","t":"القول فى الفرق بين الارادة والاختيار وفى السعادة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فعندما تحصل هذه المعقولات للانسان يحدث له بالطبع تأمل وروية وذكر وتشوق الى الاستنباط ونزوع الى بعض ما عقله وشوق اليه والى بعض ما يستنبطه أو كراهته والنزوع الى ما أدركه بالجملة هو الارادة . فان كان ذلك عن احساس أو تخيل سمى بالاسم العام وهو الارادة . وان كان ذلك عن روية أو عن نطق فى الجملة سمي الاختيار وهذا يوجد في الانسان خاصة . وأما النزوع عن احساس أو تخيل فهو أيضاً في سائر الحيوان وحصول المعقولات الاولى للانسان هو استكماله الاول . وهذه المعقولات انما جعلت له ليستعملها في أن يصير الى استكماله الأخير .<\/span>","st":"45"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك هو السعادة وهي أن تصير نفس الانسان من الكمال في الوجود الى حيث لا تحتاج في قوامها الى مادة وذلك أن تصير في جملة الاشياء البريئة عن الاجسام وفي جملة الجواهر المفارقة للمواد وأن تبقى على تلك الحال دائماً أبداً إلا أن رتبتها تكون دون رتبة العقل الفعال . وانما تبلغ ذلك بأفعال ما ارادية بعضها أفعال فكرية . وبعضها أفعال بدنية<\/span>","st":"46"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وليست بأي أفعال اتفقت بل بأفعال ما محدودة مقدرة تحصل عن هيئات ما وملكات ما مقدرة محدودة . وذلك ان من الأفعال الارادية ما يعوق عن السعادة .<\/span>","st":"46"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والسعادة هي الخير المطلوب لذاته وليست تطلب أصلا ولا في وقت من الأوقات لينال بها شيء آخر وليس وراءها شيء آخر يمكن أن يناله الانسان أعظم منها . والافعال الارادية التي تنفع في بلوغ السعادة هي الأفعال الجميلة . والهيئات والملكات التي تصدر عنها هذه الأفعال هي الفضائل . وهذه خيرات هي لا لأجل ذواتها بل انما هي خيرات لأجل السعادة . والافعال التي تعوق عن السعادة هي الشرور وهي الأفعال القبيحة والهيئات والملكات التي عنها تكون هذه الافعال هي النقائص والرذائل والخسائس .<\/span>","st":"46"},{"sp":"HDR","t":"XXIIIa. The Faculties and Their Service"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالقوة الغاذية التي في الانسان انما جعلت لتخدم البدن وجعلت الحاسة والمتخيلة لتخدما البدن ولتخدما القوة الناطقة . وخدمة هذه الثلاثة للبدن راجعة الى خدمة القوة الناطقة إذ كان قوام الناطقة أولا بالبدن ، والناطقة منها عملية ومنها نظرية والعملية جعلت لتخدم النظرية والنظرية لا لتخدم شيئاً آخر بل ليتوصل بها الى السعادة . وهذه كلها مقرونة بالقوة النزوعية . والنزوعية تخدم الحاسة وتخدم المتخيلة وتخدم الناطقة . والقوى الخادمة المدركة ليس يمكنها ان توفي الخدمة والعمل الا بالقوة النزوعية . فان الاحساس والتخيل والروية ليست كافية في أن تفعل دون ان يقترن الى ذلك تشوق الى ما أحس أو تخيل أو روى فيه وعلم . لان الارادة هي أن تنزع بالقوة النزوعية ما أدركت<\/span>","st":"46"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذا علمت بالقوة النظرية السعادة ونصبت غاية وتشوقت بالنزوعية واستنبطت بالقوة المروية ما ينبغي أن تعمل حتى تقبل بمعاونة المتخيلة والحواس على ذلك ثم فعلت بآلات القوة النزوعية تلك الافعال . كانت افعال الانسان كلها خيرات وجميلة فاذا لم تعلم السعادة أو علمت ولم تنصب غاية بتشوق بل نصبت الغاية شيئاً آخر سواها وتشوقت بالنزوعية واستنبطت بالقوة المروية ما ينبغي أن تعمل حتى تنال بمعاونة الحواس والمتخيلة ثم فعلت تلك الافعال بآلات القوة النزوعية كانت أفعال ذلك الانسان كلها غير جميلة<\/span>","st":"47"},{"sp":"HDR","t":"القول في سبب المنامات"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والقوة المتخيلة متوسطة بين الحاسة وبين الناطقة وعند ما تكون رواضع الحاسّة كلّها تحسّ بالفعل وتفعل أفعالها تكون القوّة المتخيّلة منفعلة عنها مشغولة بما تورده الحواسّ عليها من المحسوسات وترسمه فيها. وتكون هي أيضاً مشغولة بخدمة القوّة الناطقة وبإرفاد القوّة النزوعيّة.<\/span>","st":"47"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فإذا صارت الحاسّة والنزوعيّة والناطقة على كمالاتها الأول بأن لا تفعل أفعالها مثل ما يعرض عند حال النوم. انفردت القوى المتخيّلة بنفسها فارغة عمّا تجدده الحواسّ عليها دائماً من رسوم المحسوسات وتخلّت عن خدمة القوّة الناطقة والنزوعيّة فتعود الى ما تجده عندها من رسوم المحسوسات محفوظة باقية فتفعل فيها بأن تركّب بعضها الى بعض وتفصل بعضها عن بعض ولها مع حفظها رسوم المحسوسات وتركيب بعضها الى بعض فعل ثالث وهو المحاكاة فإنّها خاصّة من بين سائر قوى النفس لها قدرة على محاكاة الأشياء المحسوسات التي تبقى محفوظة فيها.<\/span>","st":"47"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فأحياناً تحاكي المحسوسات بالحواسّ الخمس بتركيب المحسوسات المحفوظة عندها المحاكية لتلك وأحياناً تحاكي المعقولات. وأحياناً تحاكي القوّة الغاذية. وأحياناً تحاكي القوّة النزوعيّة وتحاكي أيضاً ما يصادف البدن عليه من المزاج فإنّها متى صادفت مزاج البدن رطباً حاكت الرطوبة بتركيب المحسوسات التى تحاكى الرطوبة مثل المياه والسباحة فيها ومتى كان مزاج البدن يابساً حكت يبوسة البدن بالمحسوسات التى شأنها ان تحاكى بها اليبوسة . وكذلك تحاكى حرارة البدن وبرودته اذا اتفق فى وقت من الاوقات أن كان مزاجه فى وقت ما حاراً أو بارداً<\/span>","st":"48"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقد يمكن ان كانت هذه القوة هيئة وصورة فى البدن . ان يكون البدن اذا كان على مزاج ما أن يفعل فيها البدن ذلك المزاج . غير انها لما كانت نفسانية كان قبولها لما يفعل فيها البدن من المزاج على حسب ما فى طبيعتها أن تقبله . لا على حسب ما فى طبيعة الاجسام ان تقبل المزاجات . فان الجسم الرطب متى فعل رطوبة فى جسم ما قبل الجسم المنفعل الرطوبة فصار رطباً مثل الاول . وهذه القوة متى فعل فيها رطوبة أو أدنيت اليها رطوبة لم تصر رطبة بل تقبل تلك الرطوبة بما تحاكيها من المحسوسات . كما ان القوة الناطقة متى قبلت الرطوبة فانها انما تقبل ماهية الرطوبة بان تعقلها ليست الرطوبة نفسها . كذلك هذه القوة متى فعل فيها شئ قبلت ذلك عن الفاعل على حسب ما في جوهرها واستعدادها أن تقبل ذلك.<\/span>","st":"48"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فأي شيء ما فعل فيها فإنها إن كان في جوهرها ان تقبل ذلك الشئ وكان مع ذلك في جوهرها ان تقبله كما ألقي اليها قبلت ذلك بوجهين أحدهما بأن تقبله كما هو وكما ألقي اليها. والثاني بان تحاكي ذلك الشئ بالمحسوسات التي شأنها ان تحاكي ذلك الشئ وان كان في جوهرها ان تقبل الشئ كما هو. قبلت ذلك بان تحاكي ذلك الشئ بالمحسوسات التي تصادفها عندها مما شأنها ان تحاكي ذلك الشئ ولانها ليس لها ان تقبل المعقولات معقولات. فان القوة الناطقة متى اعطتها المعقولات التي حصلت لديها لم تقبلها كما هي في القوة الناطقة لكن تحاكيها بما تحاكيها من المحسوسات ومتى اعطاها البدن المزاج الذي يتفق أن يكون له في وقت ما قبلت ذلك المزاج بالمحسوسات التي تتفق عندها مما شأنها ان تحاكي ذلك المزاج،<\/span>","st":"49"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومتى أعطيت شيئاً شأنه أن يحس قبلت ذلك احياناً كما أعطيت. وأحياناً بان تحاكي ذلك المحسوس بمحسوسات أخر تحاكيه. واذا صادفت القوة النزوعية مستعدة استعداداً قريباً لكيفية ماهيته مثل غضب أو شهوة أو لافعال ما بالجملة. حاكت القوة النزوعية فتحرکت الافعال التي شأنها ان تكون على تلك الملكة التي توجد في القوة النزوعية معدة في ذلك الوقت لقبولها . ففي مثل هذا ربما انهضت القوى الرواضع الاعضاء الخادمة لا أن تفعل في الحقيقة الافعال التي شأنها أن تكون بتلك الاعضاء عند ما تكون في القوة النزوعية تلك الافعال فتكون القوة المتخيلة بهذا الفعل أحيانا تشبه الهازل . واحيانا تشبه الميت ثم ليس بهذا فقط .<\/span>","st":"49"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولكن اذا كان مزاج البدن مزاجا شأنه أن يتبع ذلك المزاج انفعال ما في القوة النزوعية . حاكت ذلك المزاج بافعال القوة النزوعية الكائنة عن ذلك الانفعال . وذلك من قبل أن يحصل ذلك الانفعال فتنهض الاعضاء التي فيها القوة الخادمة للقوة النزوعية نحو تلك الافعال بالحقيقة . من ذلك أن مزاج البدن اذا صار مزاجا شأنه أن يتبع ذلك المزاج في القوة النزوعية شهوة النكاح . حاكت ذلك المزاج بافعال النكاح فتنهض أعضاء هذا الفعل للاستعداد نحو فعل النكاح لا عن شهوة حاصلة في ذلك الوقت . لكن لمحاكاة القوة المتخيلة للشهوة بافعال تلك الشهوة وكذلك في سائر الانفعالات .<\/span>","st":"49"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك ربما قام الانسان من نومه فضرب آخر أو قام ففر من غير أن يكون هناك وارد من خارج فيقوم ما تحاكيه القوة المتخيلة من ذلك الشئ مقام ذلك الشئ لو حصل في الحقيقة . وتحاكي أيضاً القوة الناطقة بان تحاكي ما حصل فيها من المعقولات بالاشياء التي شأنها ان تحاكي بها المعقولات فتحاكي المعقولات التي في نهاية الكمال . مثل السبب الاول والاشياء المفارقة للمادة والسموات بافضل المحسوسات وأكملها مثل الاشياء الحسنة المنظر . والمعقولات الناقصة باخس المحسوسات وانقصها مثل الاشياء القبيحة المنظر . وكذلك تحاكي تلك سائر المحسوسات اللذيذة المنظر .<\/span>","st":"50"},{"sp":"HDR","t":"XXIVa. The Active Intellect, the Rational Faculty and the Imaginative Faculty"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والعقل الفعال ما كان هو السبب في أن تصير به المعقولات التي هي بالقوة معقولات بالفعل وان يصير ما هو عقل بالقوة عقلاً بالفعل وكان ما سبيله ان يصير عقلاً بالفعل هي القوة الناطقة وكانت الناطقة ضربين ضرباً نظرياً وضرباً عملياً . وكانت العملية هي التي شأنها أن تفعل الجزئيات الحاضرة والمستقبلة . والنظرية هي التي شأنها أن تعقل المعقولات التي شأنها ان تعلم . وكانت القوة المتخيلة مواصلة لضربي القوة الناطقة .<\/span>","st":"50"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان الذي ينال القوة الناطقة عن العقل الفعال هو الشئ الذي منزلته الضياء من البصر قد يفيض منه على القوة المتخيلة فيكون للعقل الفعال في القوة المتخيلة فعل ما تعطيه أحياناً المعقولات التي شأنها ان تحصل في الناطقة النظرية . وأحياناً الجزئيات المحسوسات التي شأنها ان تحصل في الناطقة العملية فتقبل المعقولات بما يحاكيها من المحسوسات التي تركبها هي . وتقبل الجزئيات أحياناً بان تخيلها كما هي . وأحياناً بان تحاكيها بمحسوسات أخر وهذه هي التي شأن الناطقة العملية أن تعملها بالروية .<\/span>","st":"50"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فمنها حاضرة ومنها كائنة في المستقبل الا أن ما يحصل للقوة المتخيلة من هذه كلها بلا توسط رؤية فلذلك يحصل في هذه الاشياء بعد ان يستنبط بالرؤية فيكون ما يعطيه العقل الفعال للقوة المتخيلة من الجزئيات بالمنامات والرؤيات الصادقة وبما يعطيها من المعقولات التي يقبلها بان يأخذ محاكاتها مكانها بالكهانات على الاشياء الالهية .<\/span>","st":"51"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه كلها قد تكون في النوم . وقد تكون في اليقظة الا أن التي تكون في اليقظة قليلة وفي الاقل من الناس فاما التي في النوم فأكثرها الجزئيات واما المعقولات فقليلة<\/span>","st":"51"},{"sp":"HDR","t":"القول في الوحي ورؤية الملك"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك أن القوة المتخيلة اذا كانت في انسان ما قوية كاملة جداً وكانت المحسوسات الواردة عليها من خارج لا تستولى عليها استيلاء يستغرقها بأسرها ولا أخدمتها للقوة الناطقة بل كان فيها مع اشتغالها بهذين فضل كثير تفعل به أيضاً أفعالها التي تخصها وكانت حالها عند اشتغالها بهذين في وقت اليقظة مثل حالها عند تحللها منها في وقت النوم . وكثير من هذه التي يعطيها العقل الفعال فتتخيلها القوة المتخيلة بما تحاكيها من المحسوسات المرئية فان تلك المتخيلة تعود فترتسم في القوة الحاسة . فاذا حصلت رسومها في الحاسة المشتركة انفعلت عن تلك الرسوم القوة الباصرة فارتسمت فيها تلك فيحصل عما في القوة الباصرة منها رسوم تلك في الهواء المضيء الموصل للبصر المنجاز بشعاع البصر . فاذا حصلت تلك الرسوم في الهواء عاد ما في الهواء فيرتسم من رأس في القوة الباصرة التي في العين وينعكس ذلك الى الحاس المشترك والى القوة المتخيلة ولان هذه كلها متصلة بعضها ببعض . فيصير ما أعطاه العقل الفعال من ذلك مرئياً لهذا الانسان . فاذا اتفقت التي حاكت بها القوة المتخيلة تلك الاشياء محسوسات في نهاية الجمال والكمال . قال الذي يرى ذلك ان لله عظمة جليلة عجيبة ورأي أشياء عجيبة لا يمكن وجود شيء منها في سائر الموجودات أصلاً<\/span>","st":"51"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولا يمتنع أن يكون الانسان اذا بلغت قوته المتخيلة نهاية الكمال فيقبل في يقظته عن العقل الفعال الجزئيات الحاضرة والمستقبلة أو محاكياتها من المحسوسات ويقبل محاكيات المعقولات المفارقة وسائر الموجودات الشريفة ويراها. فيكون له بما قبله من المعقولات نبوّة بالاشياء الالهية. فهذا هو أكمل المراتب التي تنتهي اليها القوة المتخيلة وأكمل المراتب التي يبلغها الانسان بقوته المتخيلة. ودون هذا من يرى جميع هذه بعضها في يقظته وبعضها في نومه ومن يتخيل في نفسه هذه الاشياء كلها ولكن لا يراها يبصره. ودون هذا من يرى جميع هذه في نومه فقط.<\/span>","st":"52"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهؤلاء تكون أقاويلهم التي يعبرون بها أقاويل محاكية ورموزاً وألغازاً وابدالات وتشبيهات ثم يتفاوت هؤلاء تفاوتاً كثيراً. فمنهم من يقبل الجزئيات ويراها في اليقظة فقط ولا يقبل المعقولات ومنهم من يقبل المعقولات ويراها في اليقظة ولا يقبل الجزئيات. ومنهم من يقبل بعضها ويراها دون بعض ومنهم من يرى شيئاً في يقظته ولا يقبل بعض هذه في نومه ومنهم من لا يقبل شيئاً في يقظته بل انما يقبل ما يقبل في نومه فقط فيقبل في نومه الجزئيات ولا يقبل المعقولات . ومنهم من يقبل شيئاً من هذه وشيئاً من هذه ومنهم من يقبل شيئاً من الجزئيات فقط وعلى هذا يوجد الاكثر والناس أيضاً يتفاضلون في هذا وكل هذه معاونة للقوة الناطقة<\/span>","st":"52"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقد تعرض عوارض يتغير بها مزاج الانسان فيصير بذلك معداً لان يقبل عن العقل الفعال بعض هذه في وقت اليقظة أحياناً وفي النوم أحياناً فبعضهم يبقى ذلك فيهم زماناً وبعضهم الى وقت ما ثم يزول وقد تعرض أيضاً للانسان عوارض فيفسد بها مزاجه وتفسد تخايله فيرى أشياء مما تركبه القوة المتخيلة على تلك الوجوه مما ليس لها وجود ولا هي محاكاة لموجود وهؤلاء الممرورون والمجانين وأشباههم<\/span>","st":"53"},{"sp":"HDR","t":"القول في احتياج الانسان الى الاجتماع والتعاون"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكل واحد من الناس مفطور على أنه محتاج في قوامه وفي أن يبلغ أفضل كمالاته الى أشياء كثيرة لا يمكنه أن يقوم بها كلها هو وحده بل يحتاج الى قوم يقوم له كل واحد منهم بشيء مما يحتاج اليه . وكل واحد من كل واحد بهذه الحال فلذلك لا يمكن أن يكون الانسان ينال الكمال الذي لأجله جعلت له الفطرة الطبيعية الا باجتماعات جماعة كثيرة متعاونين يقوم كل واحد لكل واحد ببعض ما يحتاج اليه في قوامه فيجتمع مما يقوم به جملة الجماعة لكل واحد جميع ما يحتاج اليه في قوامه وفي أن يبلغ الكمال . ولهذا كثرت أشخاص الانسان فحصلوا في المعمورة من الارض فحدثت منها الاجتماعات الانسانية .<\/span>","st":"53"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فمنها الكاملة ومنها غير الكاملة . والكاملة ثلاث . عظمى . ووسطى وصغرى . فالعظمى اجتماعات الجماعة كلها في المعمورة . والوسطى اجتماع أمة في جزء من المعمورة والصغرى اجتماع أهل مدينة في جزء من مسكن أمة .<\/span>","st":"53"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وغير الكاملة أهل القرية واجتماع أهل المحلة ثم اجتماع في سكة ثم اجتماع في منزل . وأصغرها المنزلة . والمحلة والقرية هما جميعا لاهل المدينة . الا أن القرية للمدينة على انها خادمة للمدينة . والمحلة للمدينة على أنها جزءوها . والسكة جزء المحلة . والمنزل جزء السكة . والمدينة جزء مسكن أمة . والامة جزء جملة أهل المعمورة<\/span>","st":"53"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالخير الافضل والكمال الاقصى انما ينال أولا بالمدينة لا بالاجتماع الذى هو أنقص منها . ولما كان شأن الخير في الحقيقة أن يكون ينال بالاختيار والارادة . وكذلك الشرور انما تكون بالارادة والاختيار . أمكن أن تجعل المدينة للتعاون على بلوغ بعض الغايات التي هي شرور .<\/span>","st":"54"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فلذلك كل مدينة يمكن أن ينال بها السعادة فالمدينة التي يقصد بالاجتماع فيها التعاون على الاشياء التي تنال بها السعادة في الحقيقة . هي المدينة الفاضلة . والاجتماع الذي به يتعاون على نيل السعادة هو الاجتماع الفاضل . والامة التي تتعاون مدنها كلها على ما تنال به السعادة هي الامة الفاضلة . وكذلك المعمورة الفاضلة انما تكون . اذا كانت الامة التي فيها يتعاونون على بلوغ السعادة .<\/span>","st":"54"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدينة الفاضلة تشبه البدن التام الصحيح الذي تتعاون أعضاؤه كلها على تتميم حياة الحيوان وعلى حفظها عليه<\/span>","st":"54"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكما أن البدن أعضاؤه مختلفة متفاضلة الفطرة والقوى وفيها عضو واحد رئيس وهو القلب . وأعضاؤه تقرب مراتبها من ذلك الرئيس وكل واحد منها جعلت فيه بالطبع قوة يفعل بها فعله ابتغاء لما هو بالطبع غرض ذلك العضو الرئيس . وأعضاء أخر فيها قوى تفعل أفعالها على حسب أغراض هذه التي ليس بينها وبين الرئيس واسطة . فهذه في الرتبة الثانية وأعضاء أخر تفعل الأفعال على حسب غرض هؤلاء الذين في هذه المرتبة الثانية. ثم هكذا الى أن تنتهي الى أعضاء تخدم ولا ترؤس أصلا<\/span>","st":"54"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك المدينة أجزاؤها مختلفة الفطرة متفاضلة الهيئات. وفيها انسان هو رئيس وآخر يقرب مراتبها من الرئيس. وفي كل واحد منها هيئة وملكة يفعل بها فعلا يقتضى به ماهو مقصود ذلك الرئيس. وهؤلاء هم أولو المراتب الأول ودون هؤلاء قوم يفعلون الأفعال على حسب أغراض هؤلاء. وهؤلاء هم في الرتبة الثانية. ودون هؤلاء أيضا من يفعل الافعال على حسب أغراض هؤلاء. ثم هكذا تترتب أجزاء المدينة الى أن ننتهي الى أخر يفعلون أفعالهم على حسب أغراضهم فيكون هؤلاء هم الذين يخدمون ولا يخدمون ويكونون في أدنى المراتب ويكونون هم الاسفلين.<\/span>","st":"54"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">غير أن أعضاء البدن طبيعية. والهيئات التي لها قوى طبيعية وأجزاء المدينة. وان كانوا طبيعيين فان الهيئات والملكات التي يفعلون بها أفعالهم للمدينة ليست طبيعية بل ارادية. على أن أجزاء المدينة مفطورون بالطبع بفطر متفاضلة يصلح بها انسان لانسان لشئ دون شئ. غير أنهم ليسوا أجزاء المدينة بالفطر التي لهم وحدها بل بالملكات الارادية التي تحصل لها وهي الصناعات وما شاكلها. والقوى التي هي أعضاء البدن بالطبع . فان نظائرها في أجزاء المدينة ملكات وهيآت ارادية<\/span>","st":"55"},{"sp":"HDR","t":"القول في العضو الرئيس"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكما أن العضو الرئيس في البدن هو بالطبع أكمل أعضائه وأتمها في نفسه وفيما يخصه وله من كل ما يشارك فيه عضو آخر أفضلها . ودونه أيضاً أعضاء أخرى رئيسة لما دونها ورياستها دون رياسة الاول وهي تحت رياسة الاول ترأس وترأس . كذلك رئيس المدينة هو أكمل أجزاء المدينة فيما يخصه وله من كل ما شارك فيه غيره أفضله . ودونه قوم مرؤوسون منه ويرأسون آخرين .<\/span>","st":"55"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكما أن القلب يتكون أولا ثم يكون هو السبب في أن يكون سائر أعضاء البدن . والسبب في أن يحصل لها قواها وان تترتب مراتبها فاذا اختل منها عضو كان هو المرفد بما يزيل عنه ذلك الاختلال . كذلك رئيس هذه المدينة ينبغي أن يكون هو أولا ثم يكون هو السبب في أن تحصل المدينة وأجزاؤها . والسبب في أن يحصل الملكات الارادية التي لاجزائها في أن تترتب مراتبها . وان اختل منها جزء كان هو المرفد له بما يزيل عنه اختلاله<\/span>","st":"55"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكما أن الأعضاء التي تقرب من العضو الرئيس تقوم في الافعال الطبيعية التي هي على حسب غرض الرئيس الاول بالطبع بما هو شرف. وما هو دونها من الأعضاء يقوم في الافعال بما هو دون ذلك في الشرف الى ان ينتهي الى الاعضاء التي يقوم بها من الافعال أخس. كذلك الاجزاء التي تقرب في الرياسة من رئيس المدينة تقوم من الافعال الارادية بما هو أشرف. ومن دونهم بما هو دون ذلك في الشرف الى ان ينتهي الى الاجزاء التي تقوم من الافعال باخسّها.<\/span>","st":"56"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وخسة الافعال ربما كانت بخسة موضوعاتها فان كانت الافعال عظيمة الغناء مثل فعل المثانة وفعل الامعاء السفلى في البدن وربما كانت لقلة غنائها وربما كانت لاجل انها كانت سهلة جداً كذلك في المدينة. وكذلك كل جملة كانت اجزاؤها مؤتلفة منتظمة مرتبطة بالطبع فان لها رئيساً حاله من سائر الأجزاء هذه الحال.<\/span>","st":"56"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وتلك أيضاً حال الموجودات فان السبب الأول نسبته الى سائر الموجودات كنسبة ملك المدينة الفاضلة الى سائر أجزائها فان البرية من المادة تقرب من الأول ودونها الاجسام السماوية. ودون السماوية الاجسام الهيولانية وكل هذه تحتذى حذو السبب الأول وتؤمه وتقتفيه ويفعل ذلك كل موجود بحسب قوته. الا أنها انما تقتفي الغرض بمراتب وذلك أن الاخس يقتفي غرض ماهو فوقه قليلا . وذلك يقتفي غرض ماهو فوقه وأيضاً كذلك للثالث غرض ماهو فوقه الى ان تنتهي الى التي ليس بينها وبين الأول واسطة أصلاً . فعلى هذا الترتيب تكون الموجودات كلها تقتفي غرض السبب الأول فالتي أعطيت كل مابه وجودها من أول الامر فقد احتذى بها من أول أمرها حذو الأول ومقصده . فعادت وصارت في المراتب العالية . وأما التي لم تعط من أول الأمر كل مابه وجودها فقد أعطيت قوة تتحرك بها نحو ذلك الذي يتوقع نيله ويقتفي في ذلك ماهو غرض الأول .<\/span>","st":"56"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك ينبغي ان تكون المدينة الفاضلة فان أجزاءها كلها ينبغي ان تحتذي بافعالها حذو مقصد رئيسها الأول على الترتيب .<\/span>","st":"57"},{"sp":"HDR","t":"XXVIIb. Rulership and the Intellect"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ورئيس المدينة الفاضلة ليس يمكن أن يكون أي انسان اتفق لان الرئاسة انما تكون بشيئين . أحدهما ان يكون بالفطرة والطبع معداً لها . والثاني بالهيئة والملكة الارادية ، والرئاسة التي تحصل لمن فطر بالطبع معداً لها فليس كل صناعة يمكن ان يرأس بها بل أكثر الصنائع صنائع يخدم بها في المدينة . وأكثر الفطر هي فطر الخدمة وفي الصنائع صنائع يرأس بها ويخدم بها صنائع أخر . وفيها صنائع يخدم بها فقط ولا يرأس بها أصلا.<\/span>","st":"57"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فكذلك ليس يمكن ان تكون صناعة رئاسة المدينة الفاضلة أي صناعة ما اتفقت ولا أي مملكة ما اتفقت. وكما أن الرئيس الأول في جنس لا يمكن ان يرأسه شئ من ذلك الجنس مثل رئيس الأعضاء. فانه هو الذي لا يمكن أن يكون عضو آخر رئيسا عليه. وكذلك في كل رئيس في الجملة. كذلك الرئيس الأول للمدينة الفاضلة ينبغي أن تكون صناعته صناعة لا يمكن ان يخدم بها أصلا ولا يمكن فيها ان يرأسها صناعة أخرى أصلا بل تكون صناعته صناعة نحو غرضها تؤم الصناعات كلها واياه يقصد بجميع أفعال المدينة الفاضلة<\/span>","st":"57"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويكون ذلك الانسان انسانا لا يكون يرأسه انسان أصلا. وانما يكون ذلك الانسان انسانا قد استكمل فصار عقلا ومعقولا بالفعل قد استكملت قوته المتخيلة بالطبع غاية الكمال على ذلك الوجه الذي قلنا وتكون هذه القوة منه معدة بالطبع لتقبل إما في وقت اليقظة أو في وقت النوم عن العقل الفعال الجزئيات. اما بنفسها واما بما يحاكيها ثم المعقولات بما يحاكيها وان يكون عقله المنفعل قد استكمل بالمعقولات كلها حتى لا يكون يبقي عليه منها شيء وصار عقلا بالفعل<\/span>","st":"57"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاي انسان استكمل عقله المنفعل بالمعقولات كلها . صار عقلا بالفعل ومعقولا بالفعل وصار المعقول منه هو الذى يعقل . حصل له حينئذ عقل ما بالفعل رتبته فوق العقل المنفعل أتم وأشد مفارقة للمادة ومقاربة من العقل الفعال ويسمى العقل المستفاد ويصير متوسطاً بين العقل المنفعل وبين العقل الفعال ولا يكون بينه وبين العقل الفعال شئ آخر . فيكون العقل المنفعل كالمادة والموضوع للعقل المستفاد . والعقل المستفاد كالمادة والموضوع للعقل الفعال . والقوة الناطقة التى هى هيئة طبيعية تكون مادة موضوعة للعقل المنفعل الذى هو بالفعل عقل<\/span>","st":"57"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأول الرتبة التى بها الانسان انسان هو ان تحصل الهيئة الطبيعية القابلة المعدة لان يصير عقلا بالفعل وهذه هى المشتركة للجميع فبينها وبين العقل الفعال رتبتان أن يحصل العقل المنفعل بالفعل . وأن يحصل العقل المستفاد وبين هذا الانسان الذى بلغ هذا المبلغ من أول رتبة الانسانية وبين العقل الفعال رتبتان .<\/span>","st":"58"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واذا جعل العقل المنفعل الكامل والهيئة الطبيعية كشئ واحد على مثال ما يكون المؤتلف من المادة والصورة شيئاً واحداً . واذا أخذ هذا الانسان صورة انسانية هو العقل المنفعل الحاصل بالفعل كان بينه وبين العقل الفعال رتبة واحدة فقط . واذا جعلت الهيئة الطبيعية مادة العقل المنفعل الذى صار عقلا بالفعل . والمنفعل مادة المستفاد . والمستفاد مادة العقل الفعال . وأخذت جملة ذلك كشئ واحد . كان هذا الانسان هو الانسان الذى حل فيه العقل الفعال .<\/span>","st":"58"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واذا حصل ذلك في كلا جزئي قوته الناطقة وهما النظرية والعملية ثم في قوته المتخيلة كان هذا الانسان هو الذى يوحى اليه فيكون الله عز وجل يوحى اليه بتوسط العقل الفعال فيكون ما يفيض من الله تبارك وتعالى الى العقل الفعال يفيضه العقل الفعال الى عقله المنفعل بتوسط العقل المستفاد ثم الى قوته المتخيلة فيكون بما يفيض منه الى عقله المنفعل حكيما فيلسوفا ومتعقلا على التمام وبما يفيض منه الى قوته المتخيلة نبيا منذرا بما سيكون ومخبرا بما هو الآن من الجزئيات بوجود يعقل فيه الالهى<\/span>","st":"58"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذا الانسان هو في أكمل مراتب الانسانية وفي أعلى درجات السعادة وتكون نفسه كاملة متحدة بالعقل الفعال على الوجه الذى قلنا وهذا الانسان هو الذى يقف على كل فعل يمكن أن يبلغ به السعادة فهذا أول شرائط الرئيس ثم أن يكون له مع ذلك قدرة بلسانه على جودة التخيل بالقول لكل ما يعلمه . وقدرة على جودة الارشاد الى السعادة والى الأعمال التى بها يبلغ السعادة . وأن يكون له مع ذلك جودة ثبات ببدنه لمباشرة أعمال الجزئيات .<\/span>","st":"59"},{"sp":"HDR","t":"القول فى خصال رئيس المدينة الفاضلة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فهذا هو الرئيس الذى لا يرأسه انسان آخر أصلاً وهو الامام وهو الرئيس الاول للمدينة الفاضلة وهو رئيس الأمة الفاضلة ورئيس المعمورة من الارض كلها ولا يمكن أن تصير هذه الحال الا لمن اجتمعت فيه بالطبع اثنتا عشرة خصلة قد فطر عليها .<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">أحدها أن يكون تام الاعضاء . قواها مؤاتية أعضاءها على الاعمال التى شأنها أن تكون بها . ومتى هم عضواً من أعضائه بعمل يكون به أتى عليه بسهولة .<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم أن يكون بالطبع جيد الفهم والتصور لكل ما يقال له فيلقاه بفهمه على ما يقصده القائل وعلى حسب الامر فى نفسه .<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون جيد الحفظ لما يفهمه ولما يراه ولما يسمعه ولما يدركه وفى الجملة لا يكاد ينساه .<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون جيد الفطنة ذكياً اذا رأى الشئ بأدنى دليل فطن له على الجهة التى دل عليها الدليل .<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون حسن العبارة يؤاتيه لسانه على ابانة كل ما يضمره ابانة تامة<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون محباً للتعليم والاستفادة منقاداً له سهل القبول لا يؤلمه تعب التعليم ولا يؤذيه الكدّ الذى يناله منه .<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون غير شره على المأكول والمشروب والمنكوح متجنباً بالطبع للعب مبغضاً للذات الكائنة عن هذه<\/span>","st":"59"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون محباً للصدق وأهله مبغضاً للكذب وأهله .<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون كبير النفس محباً للكرامة . تكبر نفسه بالطبع عن كل ما يشين من الامور . وتسمو نفسه بالطبع الى الارفع منها .<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان يكون الدرهم والدينار وسائر أعراض الدنيا هيئة عنده .<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم أن يكون بالطبع محباً للعدل وأهله ومبغضاً للجور والظلم وأهلهما يعطى النصف من أهله ومن غيره ويحث عليه ويؤتى من حل به الجور مؤاتياً لكل ما يراه حسناً وجميلاً .<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم أن يكون عدلاً غير صعب القياد ولا جموحاً ولا لجوجاً اذا دعى الى العدل بل صعب القياد اذا دعى الى الجور والى القبيح .<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم أن يكون قوى العزيمة على الشيء الذى يرى أنه ينبغى أن يفعل جسوراً عليه مقداماً غير خائف ولا ضعيف النفس .<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واجتماع هذه كلها في انسان واحد عسرٌ فلذلك لا يوجد من فطر على هذه الفطرة الا الواحد بعد الواحد والأقل من الناس . فان وجد مثل هذا في المدينة الفاضلة ثم حصلت فيه بعد أن يكبر تلك الشرائط الست المذكورة قبل أو الخمس منها دون الأنداد من جهة القوة المتخيلة كان هو الرئيس. وان اتفق أن لا يوجد مثله في وقت من الأوقات، أخذت للشرائع والسنن التي شرعها هذا الرئيس وأمثاله ان كانوا توالوا في المدينة فأثبتت<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويكون الرئيس الثاني الذي يخلف الاول من اجتمعت فيه من مولده وصباه تلك الشرائط، ويكون بعد كبره فيه ست شرائط. أحدها أن يكون حكيماً. والثاني أن يكون عالماً حافظاً للشرائع والسنن والسير التي دبرها الاولون للمدينة محتذياً بأفعاله كلها حذو تلك بتمامها. والثالث أن يكون له جودة استنباط فيما لا يحفظ عن السلف فيه شريعة ويكون فيما يستنبطه من ذلك محتذياً حذو الأئمة الأولين. والرابع أن يكون له جودة روية وقوة استنباط لما سبيله أن يعرف في وقت من الأوقات الحاضرة من الأمور والحوادث التي تحدث مما ليس سبيلها أن يسير فيه الأولون ويكون متجرباً بما يستنبطه من ذلك صلاح حال المدينة.<\/span>","st":"60"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والخامس أن يكون له جودة ارشاد بالقول الى شرائع الاولين والى التي استنبط بعدهم مما احتذى فيه حذوهم<\/span>","st":"61"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والسادس أن يكون له جودة ثبات ببدنه في مباشرة أعمال الحرب وذلك أن يكون معه الصناعة الحربية الخادمة والرئيسة<\/span>","st":"61"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذا لم يوجد انسان واحد اجتمعت فيه هذه الشرائط ولكن وجد اثنان . أحدهما حكيم . والثاني فيه الشرائط الباقية كأنهما رئيسين في هذه المدينة فاذا تفرقت هذه في جماعة وكانت الحكمة في واحد . والثاني في واحد . والثالث في واحد والرابع في واحد . والخامس في واحد . والسادس في واحد وكانوا متلائمين كانوا هم الرؤساء الأفاضل . فمتى اتفق في وقت ما ان لم تكن الحكمة جزء الرياسة وكانت فيها سائر الشرائط بقيت المدينة الفاضلة بلا ملك . وكان الرئيس القائم بأمر هذه المدينة ليس بملك . وكانت المدينة تعرض للهلاك . فان لم يتفق أن يوجد حكيم تضاف اليه لم تلبث المدينة بعد مدة أن تهلك<\/span>","st":"61"},{"sp":"HDR","t":"القول في مضادات المدينة الفاضلة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدينة الفاضلة تضاد المدينة الجاهلية والمدينة الفاسقة والمدينة المتبدلة والمدينة الضالة . ويضادها أيضاً من أفراد الناس نوائب المدن .<\/span>","st":"61"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدينة الجاهلية هي التي لم يعرف أهلها السعادة ولا خطرت ببالهم . إن أرشدوا اليها فلم يقيموها ولم يعتقدوها وانما عرفوا من الخيرات بعض هذه التي هي مظنونة في الظاهر انها خيرات من التي تظن أنها هي الغايات في الحياة وهي سلامة الابدان واليسار والتمتع باللذات وأن يكون مخلى هواه وأن يكون مكرما ومعظما . فكل واحد من هذه سعادة عند أهل الجاهلية . والسعادة العظمى الكاملة هي اجتماع هذه كلها . وأضدادها هي الشقاء وهي آفات الابدان والفقر وأن لا يتمتع باللذات وأن لا يكون مخلى هواه وأن لا يكون مكرما .<\/span>","st":"61"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهي تنقسم الى جماعة مدن . منها المدينة الضرورية وهي التي قصد أهلها الاقتصار على الضروري مما به قوام الأبدان من المأكول والمشروب والملبوس والمسكون والمنكوح والتعاون على استفادتها .<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدينة البدّالة هي التي قصد أهلها أن يتعاونوا على بلوغ اليسار والثروة ولا ينتفعوا باليسار في شئ آخر لكن على أن اليسار هو الغاية في الحياة<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومدينة الخسة والشقوة وهي التي قصد أهلها التمتع باللذة من المأكول والمشروب والمنكوح وبالجملة اللذة من المحسوس والتخيل وايثار الهزل واللعب بكل وجه ومن كل نحو .<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومدينة الكرامة وهي التي قصد أهلها على أن يتعاونوا على أن يصيروا مكرمين ممدوحين مذكورين مشهورين بين الأمم ممجدين معظمين بالقول والفعل ذوي فخامة وبهاء إما عند غيرهم واما بعضهم عند بعض كل انسان على مقدار محبته لذلك أو مقدار ما أمكنه بلوغه منه .<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومدينة التغلب وهي التي قصد أهلها أن يكونوا القاهرين لغيرهم الممتنعين أن يقهرهم غيرهم ويكون كدهم اللذة التي تنالهم من الغلبة فقط .<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدينة الجماعية هي التي قصد أهلها أن يكونوا أحراراً يعمل كل واحد منهم ما شاء لا يمنع هواه في شيء أصلاً .<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وملوك الجاهلية على عهد مدنها أن يكون كل واحد منهم انما يدبر المدينة التي هو مسلط عليها ليحصل هواه وميله وهمم الجاهلية التي يمكن أن تجعل غايات هي تلك التي أحصيناها آنفاً .<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأما المدينة الفاسقة وهي التي آراؤها الآراء الفاضلة وهي التي تعلم السعادة والله عز وجل والثواني والعقل الفعال وكل شيء سبيله أن يعلمه أهل المدينة الفاضلة ويعتقدونها ولكن تكون أفعال أهلها أفعال أهل المدن الجاهلية .<\/span>","st":"62"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدينة المبدلة فهي التي كانت آراؤها وأفعالها في القديم آراء المدينة الفاضلة وأفعالها غير أنها تبدلت فدخلت فيها آراء غير تلك واستحالت أفعالها الى غير تلك .<\/span>","st":"63"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدينة الضارة هي التي تظن بعد حياتها هذه السعادة ولكن غيرت هذه وتعتقد في الله عز وجل وفي الثواني وفي العقل الفعال آراء فاسدة لا يصلح عليها ولا ان أخذت على انها تمثيلات وتخييلات لها ويكون رئيسها الاول ممن أوهم أنه يوحى اليه من غير أن يكون كذلك ويكون قد استعمل في ذلك التنويهات والمخادعات والغرور. وملوك هذه المدن مضادة لملوك المدن الفاضلة ورياستهم مضادة للرياسات الفاضلة وكذلك سائر من فيها<\/span>","st":"63"},{"sp":"HDR","t":"XXIXb. The People of the Virtuous City and Their Souls"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وملوك المدن الفاضلة الذين يتوالون في الأزمنة المختلفة واحداً بعد آخر كلهم كنفس واحدة وكأنهم ملك واحد يبقى الزمان كله. وكذلك ان اتفق منهم جماعة في وقت واحد إما في مدينة واحدة واما في مدن كثيرة فان جماعتهم كملك واحد ونفوسهم كنفس واحدة.<\/span>","st":"63"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك أهل كل رتبة منها متى توالوا في الازمان المختلفة فكلهم كنفس واحدة تبقى الزمان كله. وكذلك ان كان في وقت واحد جماعة من أهل رتبة واحدة وكانوا في مدينة واحدة أو مدن كثيرة. فان نفوسهم كنفس واحدة كانت تلك الرتبة رتبة رياسة أو رتبة خدمة<\/span>","st":"63"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأهل المدينة الفاضلة لهم أشياء مشتركة يعلمونها ويفعلونها وأشياء أخر من علم وعمل يخص كل رتبة وكل واحد منهم. انما يصير في حد السعادة بهذين أعني بالمشترك الذي له ولغيره معاً وبالذي يخص أهل المرتبة التي هو منها . فاذا فعل ذلك كل واحد منهم أكسبته أفعاله تلك هيئة نفسانية جيدة فاضلة وكلما داوم عليها أكثر صارت هيئته تلك أقوى وأفضل وتزايدت قوتها وفضيلتها . كما أن المداومة على الافعال الجيدة من أفعال الكتابة تكسب الانسان جودة وصناعة الكتابة وكلما داوم على تلك الافعال أكثر صارت الصناعة التي بها تكون تلك الافعال أقوى وأفضل وتزيد قوتها وفضيلتها بتكرير أفعالها ويكون الالتذاذ التابع لتلك الهيئة النفسانية أكثر واغتباط الانسان عليها نفسه أكثر ومحبته لها أزيد .<\/span>","st":"63"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وتلك حال الافعال التي ينال بها السعادة . فانها كلما زيدت منها وتكررت وواظب الانسان عليها صيرت النفس التي شأنها أن تسعد أقوى وأفضل وأكمل الى أن تصير من حد الكمال الى أن تستغنى عن المادة فتحصل متبرئة منها فلا تتلف بتلف المادة . ولا اذا بقيت احتاجت الى مادة .<\/span>","st":"64"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذا حصلت مفارقة للمادة غير متجسمة ارتفعت عنها الاعراض التي تعرض للاجسام من جهة ماهي أجسام فلا يمكن فيها أن يقال انها تتحرك ولا انها تسكن . وينبغى حينئذ ان يقال عليها الاقاويل التى تليق بما ليس بجسم وكلما وقع فى نفس الانسان من شئ يوصف به الجسم بما هو جسم فينبغى أن يسلب عن الأنفس المفارقة ويفهم حالها هذه . وتصورها عسير غير معتاد . وكذلك يرتفع عنها كل ما كان يلحقها ويعرض لها بمفارقتها للاجسام<\/span>","st":"64"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولما كانت فى هذه الانفس التى فارقت أنفس . كانت فى هيوليات مختلفة وكان يبين أن الهيئات النفسانية تتبع مزاجات الابدان بعضها أكثر وبعضها أقل وتكون كل هيئة نفسانية على نحو ما يوجبه مزاج البدن الذى كانت فيه . فهيئتها لزم فيها ضرورة أن تكون متغيرة لاجل التغير الذى فيها كان . ولما كان تغاير الأبدان الى غير نهاية محدودة كانت تغايرات الانفس أيضاً الى غير نهاية محدودة<\/span>","st":"64"},{"sp":"HDR","t":"القول فى اتصال النفوس بعضها ببعض"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واذا مضت طائفة فبطلت أبدانها وخلصت أنفسها وسعدت فخلفهم ناس آخرون فى مرتبتهم بعدهم قاموا مقامهم وفعلوا أفعالهم فاذا مضت هذه أيضاً وخلت صاروا أيضاً فى السعادة الى مراتب أولئك الماضين واتصل كل واحد بشبيهه فى النوع والكمية والكيفية ولانها كانت ليست باجسام صار اجتماعها ولو بلغ مابلغ غير مضيق بعضها على بعض مكانها . اذ كانت ليست في أمكنة أصلا فتلافيها واتصال بعضها ببعض ليس على النحو الذي توجد عليه الاجسام وكلما كثرت الأنفس المتشابهة المفارقة واتصل بعضها ببعض وذلك على جهة اتصال معقول بمعقول كان التذاذ كل واحدة منها أزيد شديداً . وكلما لحق بهم من بعدهم زاد التذاذ من لحق الآن بمصادفة الماضين وزادت لذات الماضين باتصال اللاحقين بهم لان كل واحدة تعقل ذاتها . وتعقل مثل ذاتها مراراً كثيرة فتزداد كيفية ما يعقل<\/span>","st":"64"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويكون تزايد ما تلاقى هناك . شبيهاً بتزايد قوة صناعة الكتابة بمداومة الكاتب على أفعال الكتابة ويقوم تلاحق بعض ببعض في تزايد كل واحد مقام ترادف أفعال الكتاب التي بها تتزايد كتابته قوة وفضيلة . ولان المتلاحقين الى غير نهاية يكون تزايد قوى كل واحد واحد ولذاته على غابر الزمان الى غير نهاية . وتلك حال كل طائفة مضت<\/span>","st":"65"},{"sp":"HDR","t":"القول في الصناعات والسعادات"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والسعادات تتفاضل بثلاثة أنحاء . بالنوع والكمية والكيفية . وذلك شبيه بتفاضل الصنائع ههنا . فتفاضل الصنائع بالنوع هو ان تكون صناعات مختلفة بالنوع . وتكون احداها أفضل من الاخرى مثل الحياكة وصناعة البز وصناعة العطر وصناعة الكناسة ومثل صناعة الرقص وصناعة الفقه ومثل الحكمة والخطابة . فبهذه الانحاء تتفاضل الصنائع التي أنواعها مختلفة .<\/span>","st":"65"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأهل الصنائع التي من نوع واحد بالكمية ان يكون كاتبان مثلا علم أحدهما من اجزاء صناعة الكتابة أكثر وآخر احتوى من أجزائها على أشياء أقل مثل ان هذه الصناعة تلتئم باجتماع علم شئ من اللغة وشئ من الخطابة وشئ من جودة الخط وشئ من الحساب فيكون بعضهم قد احتوى من هذه على جودة الخط مثلا وعلى شئ من الخطابة أو آخر احتوى على اللغة وعلى شئ من الخطابة وعلى جودة الخط . وآخر على الاربعة كلها . والتفاضل في الكيفية هو ان يكون اثنان احتويا من أجزاء الكتابة على أشياء باعيانها ويكون أحدهما أقوى فيما احتوى عليه وأكثر دراية ، فهذا هو التفاضل في الكيفية ،<\/span>","st":"65"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والسعادات تتفاضل بهذه الانحاء أيضاً . وأما أهل سائر المدن فان أفعالهم لما كانت رديئة أكسبتهم هيئات نفسانية رديئة كما ان أفعال الكتابة متى كانت رديئة على غير ما شأن الكتابة أن تكون عليها تكسب الانسان كتابة اسوأ رديئة ناقصة. وكلما ازدادت من تلك الافعال ازدادت صناعته نقصاً. وكذلك الافعال الرديئة من أفعال سائر المدن تكسب انفسهم هيئات رديئة ناقصة وكلما واظب واحد منهم على تلك الافعال ازدادت هيئته النفسانية نقصاً. فتصير أنفسهم مرضي فلذلك ربما التذوا بالهيئات التي يستفيدونها بتلك الافعال كما أن مرضى الابدان مثل كثير من المحمومين لفساد مزاجهم يستلذون الاشياء التي ليس شأنها أن يلتذ بها من الطعوم ويتأذون بالاشياء التي شأنها ان تكون لذيذة ولا يحسون بطعوم الاشياء الحلوة التي من شأنها أن تكون لذيذة كذلك مرضى الانفس بفساد تخيلهم الذي اكتسبوه بالارادة والعادة يستلذون الهيئات الرديئة والافعال الرديئة ويتأذون بالاشياء الجميلة الفاضلة أو لا يتخيلونها أصلاً.<\/span>","st":"66"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكما ان في المرضى من لا يشعر بعلته وفيهم من يظن مع ذلك أنه صحيح ويقوى ظنه بذلك حتى لا يصغى الى قول طبيب أصلاً. كذلك من كان من مرضى الانفس لا يشعر بمرضه ويظن مع ذلك أنه فاضل صحيح النفس فانه لا يصغى أصلاً الى قول مرشد ولا معلم ولا مقوم ،<\/span>","st":"66"},{"sp":"HDR","t":"القول في أهل هذه المدن"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">اما أهل المدن الجاهلية فان أنفسهم تبقي غير مستكملة بل محتاجة في قوامها الى المادة ضرورة إذ لم يرتسم فيها رسم حقيقة بشيء من المعقولات الأول اصلا . فاذا بطلت المادة التي بها كان قوامها بطلت القوى التي كان شأنها ان يكون بها قوام ما بطل وبقيت القوى التي شأنها ان يكون بها قوام ما بقي فان بطل هذا أيضاً وانحل الى شيء آخر صار الذي بقي صورة ما لذلك الشيء الذي اليه انحلت المادة الباقية فكلما يتفق بعد ذلك أن ينحل ذاك أيضاً الى شيء صار الذي يبقي صورة ما لذلك الشيء الذي اليه انحل الى ان ينحل الى الاسطقسات فيصير الباقي الاخير صورة الاسطقسات<\/span>","st":"67"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم من بعد ذلك يكون الامر فيه على ما يتفق ان يتكون عن تلك الاجزاء من الاسطقسات التي اليها انحلت هذه ،<\/span>","st":"67"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان اتفق أن تختلط تلك الاجزاء اختلاطا يكون عنه انسان عاد فصار هيئة في انسان . وان اتفق أن تختلط اختلاطاً يكون عنه نوع آخر من الحيوان أو غير الحيوان . عاد صورة لذلك الشيئ . وهؤلاء هم الهالكون والصائرون الى العدم على مثال ما يكون عليه البهائم والسباع والافاعى ،<\/span>","st":"67"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واما أهل المدينة الفاضلة فان الهيئات النفسانية التى اكتسبوها من آراء أسلافهم فهى تخلص انفسهم من المادة والهيئات النفسانية الرديئة التى اكتسبوها من الافعال الرذيلة فتقترن الى الهيئات الاولى فتكدر الاولى وتضادها فيلحق النفس من مضادة هذه لتلك أذى عظيم وتضاد تلك الهيئات هذه فيلحق هذه من تلك أيضاً أذي عظيم فيجتمع من هذين اذيان عظيمان للنفس .<\/span>","st":"67"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان هذه الهيئات المستفادة من أفعال الجاهلية هى بالحقيقة يتبعها اذى عظيم فى الجزء الناطق من النفس وانما صار الجزء الناطق لا يشعر بأذى هذه لتشاغله بما تورد عليه الحواس . فاذا انفرد دون الحواس شعر بما يتبع هذه الهيئات من الاذى ويخلصها من المادة ويفردها عن الحواس وعن جميع الاشياء الواردة عليها من خارج كما أن الانسان المغتم متى أورد الحواس عليه ما يشغله لم يتأذ بما يغمه ولم يشعر به حتى اذا انفرد دون الحواس عاد الاذى عليه .<\/span>","st":"67"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك المريض الذى يتألم متى تشاغل باشياء اما ان يقل أذاه بألم المرض . وأما ان لم يشعر بالاذى فاذا انفرد دون الاشياء التى تشغله يشعر بالاذى أو عاد عليه الاذى كذلك الجزء الناطق مادام متشاغلا بما تورده الحواس عليه لم يشعر بأذى ما يقترن به من الهيئات الرديئة حتى اذا انفرد انفراداً تاماً دون الحواس . شعر بالاذى وظهر له أذى هذه الهيئات فبقى الدهر كله في أذى عظيم . فان ألحق به من هو في مرتبته من أهل تلك المدينة ازداد أذى كل واحد منهم بصاحبه لان المتلاحقين بلا نهاية . تكون زيادات اذا هم في غابر الزمان بلا نهاية فهذا هو الشقاء المضاد للسعادة .<\/span>","st":"68"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واما أهل المدن الضالة فان الذى أضلهم وعدل بهم عن السعادة لاجل شئ من أغراض أهل الجاهلية وقد عرف السعادة فهو من أهل المدن الفاسقة فذلك هو وحده دون أهل المدينة شقى . فاما أهل المدينة أنفسهم فانهم يهلكون ويخلون على مثال ما يصير اليه حال أهل الجاهلية .<\/span>","st":"68"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واما أهل المدن المبدلة فان الذى بدل عليهم الامر وعدل بهم . إن كان من أهل المدن الفاسقة شقى هو وحده . فاما الآخرون فانهم يهلكون ويخلون أيضاً مثل أهل الجاهلية . وكذلك كل من عدل عن السعادة بسهو وغلط .<\/span>","st":"68"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">واما المضطرون والمقهورون من أهل المدينة الفاضلة على أفعال الجاهلية فان المقهور على فعل شئ لما كان يتأذى بما يفعله من ذلك . صارت مواظبته على ما قسر عليه لا تكسبه هيئة نفسانية مضادة للهيئات الفاضلة فتكدر عليه تلك الحال حتى تصير منزلته منزلة أهل المدن الفاسقة فلذلك لا تضره الافعال التى أكره عليها وانما ينال الفاضل ذلك متى كان المتسلط عليه أحد أهل المدن المضادة للمدينة الفاضلة واضطر الى ان يسكن في مساكن المضادين .<\/span>","st":"68"},{"sp":"HDR","t":"القول في الاشياء المشتركة لاهل المدينة الفاضلة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فأما الاشياء المشتركة التي ينبغى ان يعلمها جميع أهل المدينة الفاضلة فهى أشياء . أولها معرفة السبب الأول وجميع ما يوصف به .<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم الاشياء المفارقة للمادة وما يوصف به كل واحد منها بما يخصه من الصفات والمرتبة الى أن تنتهي من المفارقة الى العقل الفعال وفعل كل واحد منها<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم الجواهر السماوية وما يوصف به كل واحد منها<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم الاجسام الطبيعية التى تحتها كيف تتكون وتفسد وان ما يجرى فيها يجرى على إحكام واتقان وعناية وعدل وحكمة وانها لا اهمال فيها ولا نقص ولا جور ولا بوجه من الوجوه .<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم كون الانسان وكيف تحدث قوى النفس وكيف يفيض عليها العقل الفعال الضوء حتى تحصل المعقولات الاول والارادة والاختيار<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم الرئيس الاول وكيف يكون الوحى<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم الرؤساء الذين ينبغى أن يخلفوه اذا لم يكن هو في وقت من الاوقات<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم المدينة الفاضلة وأهلها أو السعادة التى تصير اليها أنفسهم<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدن المضادة لها<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وما تؤول اليه أنفسهم بعد الموت اما بعضهم الى السعادة واما بعضهم الى العدم .<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم الامم الفاضلة والامم المضادة لها<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه الاشياء تعرف بأحد وجهين . اما ان ترتسم في نفوسهم كما هي موجودة واما ان ترتسم فيهم بالمناسبة والتمثيل وذلك ان يحصل في نفوسهم مثالاتها التى تحاكيها .<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فحكماء المدينة الفاضلة هم الذين يعرفون هذه ببراهين وببصائر أنفسهم . ومن يلى الحكماء يعرفون هذه على ما هي عليه موجودة ببصائر الحكماء اتباعا لهم وتصديقاً لهم وثقة بهم . والباقون منهم يعرفونها بالمثالات التى تحاكيها لانهم لاهيئة في أذهانهم لتفهمهم على ما هي موجودة اما بالطبع واما بالعادة<\/span>","st":"69"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكلتاهما معروفتان . الا أن التي للحكيم أفضل لا محالة والذين يعرفونها بالمثالات التى تحاكيها بعضهم يعرفونها بمثالات قريبة منها وبعضهم بمثالات أبعد قليلا وبعضهم بمثالات أبعد من تلك وبعضهم بمثالات بعيدة جداً<\/span>","st":"70"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وتحاكى هذه الاشياء لكل أمة ولاهل كل مدينة بالمثالات التى عندهم الاعرف فالاعرف وربما اختلف عند الامم اما أكثره واما بعضه فتحاكى هذه لكل أمة بغير الامور التى تحاكى بها الامة الاخرى .<\/span>","st":"70"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فلذلك يمكن أن يكون أمم فاضلة ومدن فاضلة تختلف ملتهم فهم كلهم يؤمون سعادة واحدة بعينها ومقاصد واحدة بأعيانها .<\/span>","st":"70"},{"sp":"HDR","t":"XXXIIIb. Demonstration and Likeness"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه الاشياء المشتركة اذا كانت معلومة ببراهينها لم يمكن أن يكون فيها موضع عناد بقول أصلا لا على جهة المغالطة ولا عند من يسوء فهمه لها . فحينئذ يكون للمعاند لا حقيقة الامر فى نفسه ولكن ما فهمه هو من الباطل فى الامر .<\/span>","st":"70"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فأما اذا كانت معلومة بمثالاتها التى تحاكيها فان مثالاتها قد تكون فيها مواضع العناد أقل . وبعضها يكون فيها مواضع العناد أكثر وبعضها يكون فيه مواضع العناد أظهر وبعضها يكون فيه أخفى ولا يمتنع أن يكون فى الذين عرفوا تلك الاشياء بالمثالات المحاكية من يقف على مواضع العناد فى تلك المثالات ويتوقف عنده وهؤلاء أصناف .<\/span>","st":"70"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">صنف مسترشدون فما تزيف عند أحد من هؤلاء شيء ما رفع الى مثال آخر أقرب الى الحق لا يكون فيه ذلك العناد فان قنع به ترك وان تزيف عنده ذلك أيضاً رفع الى مرتبة أخرى فان قنع به ترك وكلما تزيف عنده مثال في مرتبة ما رفع فوقها فان تزيفنت عنده المثالات كلها كانت فيه منة للوقوف على عرف الحق وجعل في مرتبة المقلدين للحكماء فان لم يقنع بذلك وتشوق الى الحكمة كان في منتهي ذلك علمها<\/span>","st":"70"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وصنف آخرون بهم أغراض ما جاهلية من كرامة ويسار أو لذة في المال وغير ذلك ويرى شرائع المدينة الفاضلة تمنع منها فيعمد الى آراء المدينة الفاضلة فيقصد تزييفها كلها سواء كانت مثالات للحق أو كان الذي يلقى اليه منها الحق نفسه .<\/span>","st":"71"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">أما المثالات فتزييفها بوجهين . أحدهما بما فيه من مواضع العناد . والثاني بمغالطة وتمويه . وأما الحق نفسه فبمغالطة وتمويه كل ذلك لئلا يكون شئ يمنع غرضه الجاهلي والقبيح . وهؤلاء ليس ينبغي أن يجعلوا أجزاء المدينة الفاضلة .<\/span>","st":"71"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وصنف آخر تزييف عندهم المثالات كلها لما فيه من مواضع العناد ولأنهم مع ذلك سيؤو الافهام يغلطون أيضاً عن مواضع الحق من المثالات فيتزيف منها عندهم ماليس فيها موضع للعناد أصلا .<\/span>","st":"71"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذا رفعوا الى طبقة الحق حتى يعرفوها أضلهم سوء أفهامهم عنه حتى يتخيلون الحق على غير ما هو به فيظنون أيضاً ان الذى تصوروه هو الذى ادعى الحق أنه هو الحق<\/span>","st":"71"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فاذا تزيف ذلك عندهم ظنوا أن الذى تزيف هو الحق الذى يدعى أنه الحق لا الذى فهموه هم فيقع لهم لأجل ذلك انه لا حق أصلا وان الذى يظن به انه أرشد الى الحق لمغرور . وان الذى يقال فيه انه مرشد الى الحق مخادع مموه طالب بما يقول من ذلك رئاسة أو غيرها .<\/span>","st":"71"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقوم من هؤلاء يخرجهم ذلك الى أن يتحيروا وآخرون من هؤلاء يلوح لهم مثل ما يلوح الشئ من بعيد أو مثل ما يتخيله الانسان فى النوم ان الحق موجود ويباين من أدركه لاسباب يرى انها لا تتأتى له فيقصد الى تزييف ما أدركه ولا يحسبه حينئذ حقاً ثم يعلم أو يظن أنه أدرك الحق .<\/span>","st":"71"},{"sp":"HDR","t":"القول في آراء أهل المدن الجاهلة والضالة"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والمدن الجاهلة والضالة انما تحدث متى كانت الملة مبنية على بعض الآراء القديمة الفاسدة .<\/span>","st":"71"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">منها أن قوما قالوا انا نرى الموجودات التى نشاهدها متضادة . وكل واحد منها يلتمس ابطال الآخر ونرى كل واحد منها اذا حصل موجوداً أعطى مع وجوده شيئاً يحفظ به وجوده من البطلان وشيئاً يدفع به عن ذاته فعل ضده . ويجوز به ذاته عن ضده . وشيئاً يبطل به ضده ويفعل منه جسماً شبيهاً به في النوع وشيئاً يقتدر به على أن يستخدم سائر الاشياء فيما هو نافع في أفضل وجوده وفي دوام وجوده<\/span>","st":"72"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وفي كثير منها جعل له ما يقهر به كل ما يمتنع عليه وجعل كل ضد من كل ضد ومن كل ما سواه بهذه الحال حتى تخيل لنا أن كل واحد منها هو الذي قصدوا أن يجاز له وحده أفضل الوجود دون غيره فلذلك جعل له كل ما يبطل به كل ما كان ضاراً له وغير نافع له وجعل له ما يستخدم به ما ينفعه في وجوده الأفضل .<\/span>","st":"72"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فانا نرى كثيراً من الحيوان يثب على كثير من باقيها فيلتمس افسادها وابطالها من غير ان ينتفع بشيء من ذلك نفعاً يظهر كأنه قد طبع على ان لا يكون موجود في العالم غيره أو أن وجود كل ماسواه ضار له على أن يجعل وجود غيره ضاراً له وان لم يكن منه شيء آخر على أنه موجود فقط .<\/span>","st":"72"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم ان كل واحد منهما ان لم يرم ذلك التمس ان يستعبد غيره فيما ينفعه وجعل كل نوع من كل نوع بهذه الحال وفي كثير منها جعل كل شخص من كل شخص في نوعه بهذه الحال<\/span>","st":"72"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ثم جعلت هذه الموجودات أن تتغالب وتتهارب . فالأقهر منها لما سواه يكون أتم وجوداً والغالب أبداً اما ان يبطل بعضه لانه في طباعه ان وجود ذلك الشئ نقص ومضرة في وجوده هو . واما أن يستخدم بعضاً ويستعبده لانه يرى في ذلك الشئ أن وجوده لاجله هو . ويرى أشياء تجرى على غير نظام ويرى مراتب الموجودات غير محفوظة<\/span>","st":"72"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ويرى أموراً تلحق كل واحد على غير استئهال منه لما يلحقه من وجوده لا وجود لنفسها هذا وشبهه هو الذى يظهر في الموجودات التي نشاهدها ونعرفها .<\/span>","st":"72"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فقال قوم بعد ذلك ان هذه الحال طبيعة الموجودات وهذه فطرتها والتي تفعلها الاجسام الطبيعية بطبائعها هي التي ينبغي أن تفعلها الحيوانات المختارة باختياراتها واراداتها . والمروية برويتها<\/span>","st":"73"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ولذلك رأوا ان المدن ينبغي ان تكون متغالبة متهارجة لا مراتب فيها ولا نظام ولا استئهال يختص به أحد دون أحد لكرامة أو لشئ آخر وان يكون كل انسان متوحداً بكل خير هو له ان يلتمس ان يغالب غيره في كل خير يفيده وان الانسان الاقهر لكل ما يناويه هو الأسعد ثم تحدث من هذه آراء كثيرة فى المدن من آراء الجاهلية<\/span>","st":"73"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فقوم رأوا ذلك انه لا تجانس ولا ارتباط لا بطبع ولا بالارادة وأنه ينبغي أن ينقص كل انسان كل انسان وان ينافر كل واحد كل واحد ولا يرتبط اثنان الا عند الضرورة ولا يأتلفان الا عند الحاجة ثم يكون اجتماعهما على ما يجتمعان عليه بان يكون أحدهما القاهر والآخر مقهوراً . وان اضطرا لاجل شئ وارد من خارج أن يجتمعا ويأتلفا فينبغي ان يكون ذلك ريث الحاجة . وما دام الوارد من خارج يضطرهما الى ذلك فاذا زال فينبغي أن يتنافر او يفترقا وهذا هو الداء السبعى من آراء الانسانية .<\/span>","st":"73"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون لما رأوا أن المتوحد لا يمكنه أن يقوم بكل ما به اليه حاجة دون أن يكون له موازرون ومعاونون يقوم له كل واحد بشئ مما يحتاج اليه رأوا الاجتماع فقوم رأوا أن ذلك ينبغي أن يكون بالقهر بأن يكون الذى يحتاج الى موازين يقهر قوماً فيستعبدهم ثم يقهر بهم آخرين فيستعبدهم أيضاً وأنه لا ينبغى أن يكون موازره مساويا له بل مقهوراً مثل أن يكون أقواهم بدناً وسلاحا يقهر واحداً حتى اذا صار ذلك مقهوراً له . قهر به واحداً آخر أو نفراً ثم يقهر بأولئك آخرين حتى يجتمع له موازرون على الترتيب فاذا اجتمعوا له صيرهم آلات يستعملهم فيما فيه هواه.<\/span>","st":"73"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون رأوا ههنا ارتباطاً وتحاباً وائتلافاً واختلفوا في التي بها يكون الارتباط. فقوم رأوا أن الاشتراك في الولادة من والد واحد هو الارتباط به وبه يكون الاجتماع والائتلاف والتحاب والتؤازر على أن يغلبوا غيرهم وعلى الامتناع من أن يغلبهم غيرهم<\/span>","st":"74"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان التباين والتنافر بتباين الآباء والاشتراك في الوالد الأخص والأقرب يوجب ارتباطاً أشد وفيما هو أعم يوجب ارتباطاً أضعف الى أن يبلغ من العموم والبعد الى حيث ينقطع الارتباط أصلاً ويكون تنافراً فعند الضرورة الواردة من خارج مثل شر يدهمهم. لا يقومون بدفعه الا باجتماع جماعات كثيرة.<\/span>","st":"74"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقوم رأوا أن الارتباط هو بالاشتراك في التناسل. وذلك بأن ينسل ذكورة أولاد هذه الطائفة من اناث أولاد أولئك وذكورة أولاد أولئك من اناث أولاد هؤلاء. وذلك التصاهر<\/span>","st":"74"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقوم رأوا أن الارتباط هو باشتراك في الرئيس الاول الذي جمعهم أولاً ودبرهم حتى غلبوا به ونالوا خيراً ما من خيرات الجاهلية.<\/span>","st":"74"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقوم رأوا أن الارتباط هو بالايمان والتحالف والتعاهد على ما يعطيه كل انسان من نفسه ولا ينافر الباقين ولا يخاذلهم وتكون أيديهم واحدة في أن يغلبوا غيرهم وأن يدفعوا عن أنفسهم غلبة غيرهم لهم .<\/span>","st":"74"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون رأوا ان الارتباط هو بتشابه الخلق والشيم الطبيعية والاشتراك في اللغة واللسان وأن التباين يباين هذه . وهذا هو لكل أمة فينبغي أن تكون فيما بينهم متجانسين ومنافرين لمن سواهم . فان الامم انما تتباين بهذه الثلاث .<\/span>","st":"74"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون رأوا أن الارتباط هو بالاشتراك في المنزل ثم الاشتراك في المساكن وان أخصهم هو بالاشتراك في المنزل ثم الاشتراك في السكة ثم الاشتراك في المحلة فلذلك يتواسون بالجار فان الجار هو المشارك في السكة وفي المحلة ثم الاشتراك في المدينة ثم الاشتراك في الصقع الذى فيه المدينة .<\/span>","st":"74"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وههنا أيضاً أشياء يظن أنه ينبغي أن يكون لها ارتباط جزئى بين جماعة يسيرة وبين نفر وبين اثنين منها طول التلاقى ومنها الاشتراك في طعام يؤكل وشراب يشرب . ومنها الاشتراك في الصنائع ومنها الاشتراك في شر يدهمهم وخاصة متى كان نوع الشر واحداً وتلاقوا فان بعضهم يكون سلوة بعض . ومنها الاشتراك في لذة ما ومنها الاشتراك في الأمكنة التي لا يؤمن فيها ان يحتاج كل واحد الي الآخر مثل التوافق في السفر .<\/span>","st":"74"},{"sp":"HDR","t":"القول في العدل"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">قالوا فان تميزت الطوائف بعضها عن بعض بأحد هذه الارتباطات إما قبيلة عن قبيلة أو مدينة عن مدينة أو احلاف عن احلاف أو أمة عن أمة كانوا مثل تميز كل واحد عن كل واحد فانه لا فرق بين أن يتميز كل واحد عن كل واحد أو تتميز طائفة عن طائفة فينبغي بعد ذلك أن يتغالبوا و يتهارجوا والأشياء التي يكون عليها التغالب هي السلامة والكرامة واليسار واللذات وكل ما يوصل به الى هذه وينبغي أن يروم كل طائفة أن تسلب جميع ماللاخرى من ذلك وتجعل ذلك لنفسها ويكون كل واحد من كل واحد بهذه الحال فالقاهرة منها للاخرى على هذه هي الفائزة وهي المغبوطة وهي السعيدة<\/span>","st":"75"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه الاشياء هي التي في الطبع اما في طبع كل انسان أو في طبع كل طائفة وهي تابعة لما عليه طبائع الموجودات الطبيعية. فما في الطبع هو العدل<\/span>","st":"75"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالعدل اذاً التغالب والعدل هو أن يقهر ما اتفق منها والمقهور اما ان قهر على سلامة بدنه أو هلاك وتلف وانفرد القاهر بالوجود أو قهر على كراهته وبقي ذليلا ومستعبداً تستعبده الطائفة القاهرة ويفعل ماهو الانفع للقاهر في أن ينال به الخير الذي عليه الغالب ويستديم به. فاستعباد القاهر للمقهور هو أيضاً من العدل وان يفعل المقهور ماهو الأنفع للقاهر هو أيضاً عدل فهذه كلها هي العدل الطبيعي وهي الفضيلة. وهذه الأفعال هي الأفعال الفاضلة فاذا حصلت الخيرات للطائفة القاهرة فينبغي أن يعطى من هو أعظم غناء في الغلبة على تلك الخيرات من تلك الخيرات أكثر والأقل غناء فيها أقل. وان كانت الخيرات التي غلبوا عليها كرامة أعطى الأعظم غناء فيه كرامة أكثر وان كانت أموالا أعطى أكثر وكذلك في سائرها فهذا هو أيضاً عدل عندهم طبيعي<\/span>","st":"75"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">قالوا وأما سائر ما يسمى عدلا مثل ما في البيع والشراء ومثل رد الودائع ومثل أن لا يغضب ولا يجور وأشباه ذلك فان مستعمله انما يستعمله أولا لاجل الخوف والضعف وعند الضرورة الواردة من خارج.<\/span>","st":"76"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك ان يكون كل واحد منهما كأنهما نفسان أو طائفتان مساوية احداهما في قوتها للاخرى وكانا يتداولان القهر فيطول ذلك بينهما فيذوق كل واحد الامرين ويصير الى حال لا يحتملها. فحينئذ يجتمعان ويتناصفان ويترك كل واحد منهما للآخر مما كانا يتغالبان عليه قسطاً ما فتبقى سماته ويشرط كل واحد منهما على صاحبه أن لا يروم نزع ما في يديه إلا بشرائط فيصطلحان عليها فيحدث من ذلك الشرائط الموضوعة في البيع والشراء ويقارب الكرامات ثم المواساة وغير ذلك مما جانسها<\/span>","st":"76"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وإنما يكون ذلك عند ضعف كل من كل وعند خوف كل من كل فمادام كل واحد من كل واحد في هذه الحال فينبغي أن يتشاركا ومتى قوى أحدهما على الآخر فينبغي أن ينقض الشريطة ويروم القهر أو يكون الاثنان ورد عليهما من خارج شيء على أنه لا سبيل إلى دفعه إلا بالمشاركة وترك التغالب فيتشاركان ريث ذلك أو يكون لكل واحد منهما همة في شيء يريد أن يغلب عليه فيرى أنه لا يصل إليه إلا بمعاونة الآخر له وبمشاركته له فيتركان التغالب بينهما ريث ذلك ثم يتعاونان<\/span>","st":"76"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فإذا وقع التكافؤ من الفرق بهذه الأسباب وتمادى الزمان على ذلك ونشأ على ذلك من لم يدر كيف كان أول ذلك حسب أن العدل هو هذا الموجود الآن ولا يدرى أنه خوف وضعف فيكون مغروراً بما يستعمل من ذلك فالذي يستعمل هذه الأشياء إما ضعيف أو خائف أن يناله من غيره مثل الذي يحدث في نفسه من الشوق الى فعله.<\/span>","st":"76"},{"sp":"HDR","t":"القول في الخشوع"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وأما الخشوع فهو أن يقال ان الهاً يدبر العالم وان الروحانيين مدبرون مشرفون على جميع الافعال واستعمال تعظيم الاله والصلوات والتسابيح والتقاديس وان الانسان اذا فعل هذه وترك كثيراً من الخيرات المتشوقة في هذه الحياة وواظب على ذلك عوض عن ذلك وكوفى بخيرات عظيمة يصل اليها بعد موته. وأن هو لم يتمسك بشئ من هذه وأخذ الخيرات في حياته عوقب عليها بعد موته بشرور عظيمة ينالها في الآخرة<\/span>","st":"77"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان هذه كلها أبواب من الحيل والمكايد على قوم ولقوم فانها حيل ومصايد لمن يعجز عن المغالبة على هذه الخيرات بالمصالة والمجاهرة ومكايدة يكايد بها من لا قدرة له على المجاهرة بأخذها والمصالة بيديه وسلاحه بغير ورية ومعونة تخويفهم وقمعهم لان يتركوا هذه الخيرات كلها أو بعضها ليفوز بها آخرون<\/span>","st":"77"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فمن يعجز عن المجاهرة يأخذها أو بالغلبة عليها فان المتمسك بهذه يظن به أنه غير حريص عليها ويظن به الخير فيركن اليه ولا يحذر ولا يتقي ولا يتهم بل يخفى مقصده ويوصف سيرته أنها الالهية فيكون زيه وصورته صورة من لا يريد هذه الخيرات كلها لنفسه فيكون ذلك سبباً لان يكرم ويعظم ويؤمل بسائر الخيرات وتنقاد النفوس له فتحبه فلا تنكر ارتكاب هواه في كل شئ بل يحسن عند الجميع قبيح ما يعمله ويصير بذلك الى غلبة الجميع على الكرامات والرياسات والاموال واللذات ونيل الخيرية فتلك الاشياء انما جعلت لهذه.<\/span>","st":"77"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكما أن صيد الوحوش منه ما هو مغالبة ومجاهرة ومنه ما هو مخاتلة ومكايدة كذلك الغلبة على هذه الخيرات تكون بمطالبته وتكون بمخاتلته ويطارد بأن يتوهم الانسان في الظاهر أن مقصده شئ آخر غير الذي هو بالحقيقة مقصده ولا يحذر ولا يتقى ولا ينازع فيناله بسهولة.<\/span>","st":"78"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فالمتمسك بهذه الاشياء والمواظب عليها متى كان انما يفعل ذلك ليبلغ الشئ الذي جعل هذه لاجله وهو المواتاة بها في الظاهر ليفوز باحدى تلك الخيرات أو بجميعها وكان عند الناس مغبوطاً فيزداد يقين وحكمة وعلم ومعرفة جليلا عندهم معظما ممدوحا<\/span>","st":"78"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ومتى كان يفعل ذلك لذاته لا لينال به هذه الخيرات كان عند الناس مخدوعاً مغروراً شقياً أحمق عديم العقل جاهلا بحظ نفسه مهيناً لا قدر له مذموماً. غير أن كثيراً من الناس يظهرون مديحته لسخرية به وبعضهم يقويه لنفسه في أن لا يزاحم في شئ من الخيرات بل يتركها ليتوفر عليه وعلى غيره. وبعضهم يمدحون طريقته ومذهبه خوفاً أن يسلبهم ما عندهم من ليس هو على طريقته. وقوم آخرون يمدحونه ويغبطونه لانهم أيضاً مغرورون مثل غروره<\/span>","st":"78"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فهذه وما أشبهها هي آراء الجاهلية التى وقعت في نفوس كثير من الناس عن الاشياء التى تشاهد في الموجودات واذا حصلت لهم الخيرات التي غلبوا عليها فينبغي أن تحفظ وتستدام وتمد وتزيد فإنها ان لم يفعل بها ذلك نفدت.<\/span>","st":"78"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فقوم منهم رأوا أن يكونوا أبداً بأسرهم يطلبون مغالبة آخرين أبداً وكلما غلبوا طائفة ساروا الى أخري. وآخرون يرون أن يمتدوا ذلك من أنفسهم ومن غيرهم فيحفظونها ويدبرونها اما من أنفسهم مثل البيع والشراء والتعاوض وغير ذلك. وأما من غيرهم فبالغلبة. وآخرون رأوا تزيدها بالوجهين جميعاً.<\/span>","st":"78"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون رأوا ذلك بأن جعلوا أنفسهم قسمين قسماً يريدون تلك ويمدونها من أنفسهم بمعاملات. وقسماً يغالبون عليهم فيحصلون طائفتين كل واحدة منفردة بشيء. احداهما بالمغالبة والأخري بالمعاملة الارادية. وقوم منهم رأوا أن الطائفة المعاملة منها هي اناثهم والمغالبة هي ذكورهم واذا ضعف بعضهم عن المغالبة جعل في المعاملة فان لم يصلح لا لذا ولا لذا جعل فضلا.<\/span>","st":"78"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون رأوا ان تكون الطائفة المعاملة قوماً آخرين غير من يغلبونهم ويستعبدونهم فيكونوا هم المتولين بصورتهم ولحفظ الخيرات التي يغلبون عليها وامدادها وتزيدها.<\/span>","st":"79"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون قالوا ان التغالب في الموجودات انما هي بين الأنواع المختلفة. وأما الداخلة تحت نوع واحد فان النوع هو رابطها الذي لا جله ينبغي أن يتسالم فالانسية للناس هي الرباط فينبغي أن يتسالموا بالانسية ثم يغالبون غيرهم فيما ينتفعون به من سائرها ويتركون مالا ينتفعون به. فما كان مما لا ينتفع به ضاراً غلب على وجوده وما لم يكن ضاراً تركوه<\/span>","st":"79"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقالوا فاذا كان كذلك فان الخيرات التي سبيلها أن يكتسبها بعضهم عن بعض فينبغي أن تكون بالمعاملات الارادية والتي سبيلها أن تكتسب وتستفاد من سائر الأنواع الأخر فينبغي أن تكون بالغلبة اذ كانت الأخرى لانطق لها فتعمل المعاملات الارادية وقالوا فهذا هو الطبيعي للانسان<\/span>","st":"79"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فأما الانسان المغالب فليس بما هو مغالب طبيعياً. ولذلك اذا كان لا بد من أن يكون ههنا أمة أو طائفة خارجة عن الطبيعي للانسان تروم مغالبة سائر الطوائف على الخيرات التى بها اضطرت الأمة والطائفة الطبيعية الى قوم منهم ينفردون بمدافعة أمثال أولئك ان وردوا عليهم يطلبون مغالبتهم وبمغالبتهم على حق هؤلاء ان كانوا أولئك غلبوا عليه فتصير كل طائفة فيها قوّتان قوة تغالب بها وتدافع. وقوة تعامل بها وهذه التى بها تدافع ليست لها على أنها تفعل ذلك بارادتها لكن باضطرارها الى ذلك بما يرد عليها من خارج وهؤلاء على ضد ما عليه أولئك فان أولئك يرون ان المسالمة لا بوارد من خارج وهؤلاء يرون ان المغالبة لا بوارد من خارج فيحدث من ذلك هذا الرأى الذى للمدن المسالمة<\/span>","st":"79"},{"sp":"HDR","t":"القول في المدن الجاهلية"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">المدن الجاهلية منها الضرورية ومنها المبدلة ومنها الساقطة ومنها المكارمة ومنها الجماعية وتلك الأخرى سوى الجماعية انما همة أهلها جنس واحد من الغايات. وأما الجماعية فذات همم كثيرة قد اجتمع فيها همم جميع المدن<\/span>","st":"80"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">بالمغالبة والمدافعة التى تضطر اليها المدن المسالمة اما ان تكون فى جماعتهم. واما ان تكون فى طائفة بعينها حتى يكون أهل المدينة طائفتين طائفة فيها القوة على المغالبة والمدافعة. وطائفة ليس فيها ذلك فبهذه الاشياء يستديمون الخيرات التى هى لهم.<\/span>","st":"80"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذه الطائفة من أهل الجاهلية هي سليمة النفوس وتلك الاولى رديئة النفوس لانها ترى المغالبة هي الخير وذلك بوجهين مجاهرة ومخاتلة فمن قدر منهم على مجاهرة فعل ذلك وان لم يقدر فبالدغل والغش والمراآة والتمويه والمغالطة.<\/span>","st":"80"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والآخرون اعتقدوا أن ههنا سعادة ومما لا يصل اليه الانسان بعد موته وفى الحياة الاخرى فان ههنا فضائل وأفعالا فاضلة في الحقيقة يفعلها لينال بها السعادة بعد الموت<\/span>","st":"80"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">ونظروا فاذا ما يشاهدون في الموجودات الطبيعية لا يمكن أن ينكروه ويجحدوه وظنوا أنهم ان سلموا ان جميعه طبيعي علي ما هو مشاهد أوجب ذلك ما ظنه أهل الجاهلية فرأوا لذلك ان يقولوا ان للموجودات الطبيعية المشاهدة على هذه الحال وجوداً آخر غير الوجود المشاهد اليوم وان هذا الوجود الذي لها اليوم غير طبيعي لها بل هي مضادة لذلك الوجود الذي هو الوجود الطبيعي لها وأنه ينبغي أن يقصد بالارادة ويعمل في ابطال هذا الوجود ليحصل ذلك الوجود الذي هو الكمال الطبيعي لان هذا الوجود هو العائق عن الكمال فاذا بطل هذا حصل بعد بطلانه الكمال.<\/span>","st":"80"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون يرون أن وجود الموجودات حاصل لها اليوم ولكن اقترنت اليها واختلطت بها أشياء أخر أفسدتها وعاقتها عن أفعالها وجعلت كثيراً منها على غير صورته حتى ظن مثلاً بما ليس بانسان انه انسان. وبما هو انسان انه ليس بانسان. وبما هو فعل الانسان انه ليس بفعل له. وبما ليس بفعل له انه فعل له حتى صار الانسان فى هذا الوقت لا يفعل ما شأنه أن يفعل ويفعل ما ليس شأنه أن يفعل ويرى فى أشياء كثيرة أنها صادقة وليس كذلك. ويرى فى أشياء كثيرة أنها محالة من غير أن تكون كذلك.<\/span>","st":"81"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وعلى الرأيين جميعاً يرى ابطال هذا الوجود المشاهد ليحصل ذلك الوجود المشاهد ليحصل ذلك الوجود فان الانسان هو أحد الموجودات الطبيعية وأن الوجود الذى له الآن ليس هو وجوده الطبيعى. بل وجوده الطبيعى وجود آخر غير هذا. وهذا الذى له الآن مضاد لذلك الوجود وعائق عنه وأن الذى للانسان هو اليوم من الوجود فشئ غير طبيعى.<\/span>","st":"81"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقوم رأوا أن اقتران النفس بالبدن ليس بطبيعي وان الانسان هو النفس. واقتران البدن اليها مفسد لها مغير لافعلها. والرذائل انما تكون عنها لاجل مقارنة البدن لها وان كمالها وفضيلتها أن تخلص من البدن وأنها في سعادتها ليست تحتاج الى بدن ولا أيضاً في أن تنال السعادة تحتاج الى بدن ولا الى الاشياء الخارجة عن البدن مثل الاموال والمجاورين والاصدقاء وأهل المدينة وأن الوجود البدني هو الذي يحوج الى الاجتماعات المدنية والى سائر الاشياء الخارجة. فرأوا لذلك ان يطرح هذا الوجود البدني.<\/span>","st":"81"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون رأوا ان البدن طبيعي له ورأوا ان عوارض النفس هي التي ليست طبيعية للانسان وان الفضيلة التامة التي بها ينال السعادة هي ابطال العوارض واماتتها.<\/span>","st":"81"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقوم رأوا ذلك في جميع العوارض مثل الغضب والشهوة وأشباههما لانهم رأوا ان هذه هي أسباب ايثار هذه التي هي خيرات مظنونة وهي الكرامة واليسار واللذات وان ايثار الغلبة انما يكون بالغضب وبالقوة الغضبية. والتباين والتنافر يكون بهذا فرأوا لذلك ابطالها كلها. وقوم رأوا ذلك في الشهوة والغضب وما جانسهما وان الفضيلة والكمال ابطالهما.<\/span>","st":"82"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقوم رأوا ذلك في عوارض غير هذه مثل الغيرة والشح وأشباههما ولذلك رأى قوم ان الذي يفيد الوجود الطبيعي غير الذي يفيد الوجود الذي لنا الآن ثم ان السبب الذي عنه أحدث الشهوة والغضب وسائر عوارض النفس. مضاد للذي أفاد الجزء الناطق فجعل بعضهم بسبب ذلك تضاد الفاعلين مثل انبدقليس. وبعضهم جعل سبب ذلك تضاد المواد مثل فرمائيدس في آرائه الظاهرة وغيره من الطبيعيين<\/span>","st":"82"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وغير هذه الآراء بقدر ما يحكي عن كثير من القدماء تمت بالارادة تحى بالطبيعة فانهم يرون ان الموت موتان موت طبيعي. وموت إرادي ويعنون بالموت الارادي ابطال عوارض النفس من الشهوة والغضب. وبالموت الطبيعي مفارقة النفس الجسد ويعنون بالحياة الطبيعية الكمال والسعادة وهذا على رأي من رأى ان عوارض النفس من الشهوة والغضب قسرآ في الانسان.<\/span>","st":"82"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">والتي ذكرناها من آراء القدماء فاسدة تفرعت منها آراء انبثت منها ملل في كثير من المدن الضالة<\/span>","st":"82"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وآخرون لما شاهدوا من أحوال الموجودات الطبيعية تلك التي اقتصصنا أولا من انها توجد وجودات مختلفة متضادة وتوجد حيناً ولا توجد حيناً وسائر ما قلنا رأوا أن الموجودات التي هي الآن محسوسة أو معقولة. ليست لها جواهر محدودة ولا لشئ منها طبيعة تخصه حتى يكون جوهره هو تلك الطبيعة وحدها فقط ولا يكون غيرها بل كل واحد منها جوهره أشياء غير متناهية مثل الانسان مثلا فان المفهوم من هذا اللفظ شئ غير محدود الجوهر.<\/span>","st":"82"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">لكن جوهره وما يفهم منه أشياء لا نهاية لها غير ان ما أحسسناه الآن من جوهره هو هذا المحسوس والذى عقلنا منه هو هذا الذى نزعم ان نعقله منه اليوم. وقد يجوز ان يكون ذلك شيئاً آخر غير هذا المعقول وغير هذا المحسوس<\/span>","st":"83"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك فى كل شىء هو الآن ليس هو موجوداً. فان جوهره ليس هو هذا المعقول من لفظه فقط لكنه هذا وشىء آخر غيره مما لم نحسه ولم نعقله مما لو جعل ذلك مكان هذا الذى هو الآن موجود لأحسسناه أو لعقلناه. ولكن الذى حصل موجوداً هو هذا<\/span>","st":"83"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان لم يقل قائل ان الطبيعة طبيعة المفهوم من كل لفظ ليس هو هذا المعقول الآن لكنه أشياء أخر غير متناهية بل قال انه هذا ويجوز ان يكون غير هذا مما لم نعقله فلا فرق فى ذلك<\/span>","st":"83"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فان الذى يجوز ويمكن اذا وضع موجوداً لم يلزم منه محال وكذلك فى كل ما عندنا انه لا يجوز غيره أو لم يمكن غيره وقد يجوز أن يكون غيره وانه ليس الذى يلزم ضرورة عن تضعيف كثلاثة ثلاث مرات وجود التسعة بل ليس جوهره ذلك لكن يمكن ان يكون الحادث عن ذلك شيئاً آخر من العدد أو ما اتفق من سائر الموجودات غير المعد دأى شىء اتفق أو شيئاً آخر لم نحسسه ولم نعقله بل قد يمكن أن يكون محسوسات ومعقولات بلانهاية لم تحس بعد ولم تعقل أو لم توجد فتحس أو تعقل.<\/span>","st":"83"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وكذلك كل لازم عن شىء ما فانه ليس انما يلزم لان جوهره ذلك الشئ ألزم ذلك بل لانه هكذا اتفق ولان فاعلا من خارج ذلك الشئ كوّن الآخر عنده أو في زمان كون ذلك أو عند حال من أحواله. فانما حصول كل موجود الآن على ما هو عليه موجود اما باتفاق واما لان فاعلا من خارج أوجدها<\/span>","st":"83"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وقد كان يمكن ان يحصل بدل ما يفهم عن لفظ الانسان شيئاً آخر غير ما نعقل اليوم وشاء ذلك الفاعل أن يجعل من بين تلك التي كان يقدر ان يجعلها هذا المعقول فصرنا لا نحس ولا نفهم منه غير هذا الوجه أحداً<\/span>","st":"83"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وهذا من جنس رأي من يرى ان كل ما نعقل اليوم من شئ فقد يمكن ان يكون ضده ونقيضه هو الحق. الا ان اتفق لنا أو كد ان نجعل في أوهامنا أن الحق والصدق هو هذا الآن الذي نرى ان المفهوم من لفظ الانسان قد يمكن ان يكون شيئاً آخر غير المفهوم منه اليوم وأشياء غير متناهية على ان كل واحد من تلك هو طبيعة هذه الذات المفهومة<\/span>","st":"84"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان تلك اذ كانت هي وهذا المعقول اليوم شيئاً واحداً في العدد فليس المعقول اليوم شيئاً واحداً في العدد وليس المعقول من لفظ الانسان بشئ آخر غير هذا المعقول اليوم فان كانت ليست هي واحدة بالعدد بل كثيرة مختلفة الحدود فاسم الانسان يقال عليهما بالاشتراك<\/span>","st":"84"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان كانت مع ذلك مما يمكن ان يظهر فى الوجود معاً كانت على مثال ما يقال عليهما اسم العين اليوم ويكون أيضاً أشياء بلانهاية فى العدد معاً<\/span>","st":"84"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وان كانت مما لا يمكن ان يوجد معاً بل كانت تتعاقب فهى متضادة أو متقابلة فى الجملة وان كانت متقابلة وكانت بلانهاية أو متناهية. لزم ان يكون كل ما عندنا انه لا يجوز غيره أو نقيضه فانه يمكن ان يكون نقيضه أو ضده أو مقابله فى الجملة هو أيضاً حق. اما بدل هذا أو مع ضده فيلزم من هذا ان لا يصح قول يقال أصلاً وان يصح جميع ما يقال وان لا يكون فى الكون محالاً أصلاً<\/span>","st":"84"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">فانه ان وضع شئ ما طبيعة شئ ما جاز ان يكون غير ذلك الذى يفهم على لفظه اليوم. وطبيعة شئ ما مما لاندرى أى شئ هو مما يمكن ان يصير موجوداً فيحس أو يعقل ويصير مفهوماً. ولكن ليس هو معقولاً عندنا اليوم<\/span>","st":"84"},{"sp":"N","t":"<span class=\"hv-ar\" dir=\"rtl\" lang=\"ar\">وذلك الذى لاندرى الآن أى شئ هو وقد يمكن ان يكون ضده أو مقابله فى الجملة فيكون ما هو محال عندنا ممكناً أن لا يكون محالاً وبهذا الرأى وما جانسه تبطل الحكمة ويجعل ما يرسم فى النفوس أشياء محالة على انها حق بانها تجعل الاشياء كلها ممكنة ان توجد فى جوهرها وجودات متقابلة ووجودات بلا نهاية فى جواهرها واعراضها ولا تجعل شيئاً محالاً أصلاً<\/span>","st":"84"}],[]);})();